pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly super-linear to punish dead space
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Smooth non-linear coupling with stream progress:
    // early on, prefer compacting (low post_residual weighted); later, prefer
    // leaving room shaped like the lookahead item.
    let prog_curve = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 40.0 * prog_curve * norm_pr * (1.0 - norm_pr);

    // Lookahead shaping: reward post_residual close to next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score += 30.0 * diff * diff * cap;
        // bonus if next item fits exactly
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // Slight penalty when this bin is much tighter than average (fragmentation)
    let mr = mean_residual;
    let spread = (pr - mr) / cap;
    score += 6.0 * spread * spread * cap;

    // New-bin candidate: keep it neutral-ish unless open bins are wasteful
    if bin_residual == bin_capacity {
        score = pr + 10.0 + 20.0 * progress - 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize unusable small gaps.
    // Smallest item is 1, but treat gaps below ~10 as near-dead; gaps that
    // cannot fit the average incoming item are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Exact fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the
    // item fits comfortably; encourage closing bins when few remain.
    let pressure = open_bins_count as f64 / 12.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        // Next item won't fit here; slightly penalize leaving a tight leftover.
        score += 5.0 * (1.0 - post_residual as f64 / 30.0).max(0.0);
    }

    // New-bin candidate: only attractive when open bins are crowded or
    // the fit elsewhere is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * -2.0 + mean_residual * 0.5;
        if next_item_size > 0 {
            score -= (next_item_size as f64) * 0.1;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (tighter bins) when placing large items.
    if item_size >= 50 {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 36.0 * tightness * tightness;

    // Dead-space avoidance: tiny unusable gaps are waste.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 30.0 + (dead_threshold - post_residual) as f64 * 2.0;
    } else if post_residual >= dead_threshold && post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: reward bins whose leftover can serve the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 22.0;
            if post_residual == next_item_size {
                score -= 12.0;
            }
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 8.0;
        }
        if item_size + next_item_size == bin_residual {
            score -= 16.0;
        }
    }

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual == 0 || post_residual >= dead_threshold {
            score -= 40.0;
        }
    }

    // Open-bin pressure: mild, scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.8 + 1.2 * progress);

    // Pull toward mean residual (balanced packing).
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: high baseline cost; only attractive when existing
    // fits would leave dead gaps or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.6 + 20.0 * progress;
        if bin_residual >= item_size && post_residual < dead_threshold {
            score -= 25.0;
        }
        // If no open bin fits well, opening fresh is reasonable.
        if fitting_bins_count == 0 && item_size > mean_residual as u32 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let dr = post_residual as f64;

    // Tightness reward (strengthened).
    let tightness = 1.0 - (dr / cap);
    score -= 40.0 * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: small residuals are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Harmonic classes of capacity.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (dr - half).abs() < 3.0 {
        score -= 15.0;
    } else if (dr - quarter).abs() < 3.0 {
        score -= 7.0;
    }

    // Bucket preference: mildly prefer larger residuals.
    let bucket = post_residual / 10;
    score -= (bucket as f64) * 2.5;

    // Lookahead coupling: reward when next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 160.0;
            } else if slack < 8 {
                score -= 55.0;
            } else if slack < 20 {
                score -= 28.0;
            } else {
                score -= 12.0;
            }
        } else {
            if fitting_bins_count == 1 {
                score += 30.0;
            }
            if bin_residual >= next_item_size && post_residual < next_item_size {
                score += 10.0;
            }
            score += 8.0;
        }
        // Two-item exact match.
        if item_size as u64 + next_item_size as u64 == bin_residual as u64 {
            score -= 22.0;
        }
        // Waste-vs-next-item coupling: penalize leaving much more than next item needs.
        if post_residual > 0 {
            let waste = post_residual as f64 / next_item_size as f64;
            if waste >= 2.0 {
                score += 6.0 * (waste - 2.0).min(10.0);
            }
        }
    }

    // Last-chance logic: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        if post_residual == 0 {
            score -= 200.0;
        } else if post_residual >= 12 {
            score -= 48.0;
        } else if post_residual >= 6 {
            score -= 30.0;
        } else {
            score -= 18.0;
        }
    }

    // New-bin candidate: attractive only when open bins lack room for the item.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 4.0 {
            score -= 40.0;
        } else if mean_gap < 12.0 {
            score += 15.0;
        } else {
            score += 45.0 + mean_gap;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 6.0;
        if open_bins_count > 4 && mean_residual < item_size as f64 {
            score -= 12.0;
        }
    }

    // Balance pressure: penalize bins far below mean residual when many bins open.
    if open_bins_count > 3 {
        let dev = mean_residual - dr;
        if dev > 20.0 {
            score += dev * 0.3;
        }
    }

    // Fill-ratio term.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 13.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Mean-residual alignment.
    score += 0.22 * (mean_residual - dr);

    // Grid alignment bonus.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), non-linearly scaled
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr;

    // Reward using existing bins when few bins fit the item (last-chance bonus)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Penalize dead space relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual).abs() / cap;

    // Coupling: post_residual vs lookahead item — reward residual that can host next item
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        if nxt <= pr {
            score -= 6.0 * (1.0 - nxt / cap) * (1.0 - progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for opening new bins late in stream (empty-bin candidate)
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let dr = post_residual as f64;

    // Tight-fit reward (quadratic).
    let tightness = 1.0 - (dr / cap);
    score -= 38.0 * tightness * tightness;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance with graduated penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 28.0 + (10 - post_residual) as f64 * 2.5;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }
    // Bucketed residual bonus: reward larger leftover buckets slightly.
    score -= ((post_residual / 10) as f64) * 2.0;

    // Lookahead: reward bins whose leftover serves the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 140.0;
            } else if slack < 10 {
                score -= 45.0;
            } else {
                score -= 22.0;
            }
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 9.0;
            if fitting_bins_count == 1 {
                score += 25.0;
            }
            score += 8.0;
        }
        if item_size as u64 + next_item_size as u64 == bin_residual as u64 {
            score -= 18.0;
        }
        // Pair-fit: residual after placing both items nearly zero.
        if bin_residual >= item_size + next_item_size {
            let pair_left = bin_residual - item_size - next_item_size;
            if pair_left < 6 {
                score -= 9.0;
            }
        }
    }

    // Last-chance bin: prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        if post_residual == 0 {
            score -= 200.0;
        } else if post_residual >= 10 {
            score -= 46.0;
        } else {
            score -= 20.0;
        }
    }

    // Prefer fuller bins, scaled by open-bin count.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 15.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Open-bin pressure with progress.
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.8 + 1.2 * progress);

    // Mean-residual pull.
    score += 0.18 * (mean_residual - dr);

    // Balance pressure: penalize bins far above mean residual when many bins open.
    if open_bins_count > 3 {
        let dev = dr - mean_residual;
        if dev > 20.0 {
            score += dev * 0.3;
        }
    }

    // New-bin candidate decision (blended with best-known gap logic).
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        let mut nb = 58.0 + open_bins_count as f64 * 0.7 + 22.0 * progress;
        if fitting_bins_count == 0 {
            nb -= 34.0;
        }
        // Strong gap-driven new-bin policy from best heuristic.
        if mean_gap < 5.0 {
            nb -= 30.0;
        } else {
            nb += 30.0 + mean_gap * 0.6;
        }
        // Avoid fresh bins when next item is small (slack is reusable).
        if next_item_size > 0 && next_item_size < 15 {
            nb += 14.0;
        }
        // Many fitting bins: keep packing into open bins.
        if fitting_bins_count > 3 {
            nb += 8.0;
        }
        // If the next item exactly fits a current residual, avoid new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            nb += 10.0;
        }
        // Early stream: be more willing to open bins to build diverse residuals.
        nb -= (1.0 - progress) * 8.0;
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
