            }
        }
    }

    // Last-chance bin: prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 46.0;
    }

    // Prefer fuller bins, scaled by open-bin count.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 15.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Open-bin pressure with progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.8 + 1.2 * progress);

    // Mean-residual pull.
    score += 0.18 * (mean_residual - post_residual as f64);

    // New-bin candidate decision (refined).
    if bin_residual == bin_capacity {
        let mut nb = 58.0 + open_bins_count as f64 * 0.7 + 22.0 * progress;
        if fitting_bins_count == 0 {
            nb -= 34.0;
        }
        // Avoid fresh bins when next item is small (slack is reusable).
        if next_item_size > 0 && next_item_size < 15 {
            nb += 14.0;
        }
        // Avoid fresh bins when existing fits leave usable slack.
        if fitting_bins_count > 0 {
            let min_waste = mean_residual - item_size as f64;
            if min_waste > 12.0 {
