        if fitting_bins_count >= 3 {
            score += 14.0;
        }
        // A fresh bin filled exactly by this item is fine; a fresh bin leaving a
        // large awkward gap that the next item cannot use is wasteful.
        if next_item_size > 0 && (bin_capacity - item_size) > 0 && (bin_capacity - item_size) < next_item_size {
            score += 8.0;
        }
