pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening.
    let mut score = norm_pr.powf(1.0 + 1.5 * fit_ratio);

    // Smooth interaction: stream progress amplifies the cost of wasted space.
    score += norm_pr * norm_pr * (0.5 + 2.0 * progress * progress);

    // Dead-space penalty: residuals too small for the smallest plausible item.
    let dead = ((20.0 - pr).max(0.0)) / cap;
    score += dead * dead * (1.0 + progress);

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 0.6 * (1.0 - gap / cap).max(0.0) * (1.0 - fit_ratio);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // New-bin candidate: penalize mildly, less so when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score += 1.0 + 0.5 * (open_bins_count as f64).sqrt() - 0.8 * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residual mod capacity fractions
    let residual_class = (post_residual * 4) / bin_capacity; // 0..3 quartile class
    let class_penalty = match residual_class {
        0 => 0.0,          // tiny leftover: nearly perfect fit
        1 => 6.0,          // quarter leftover
        2 => 14.0,         // half leftover: dead-space risk
        _ => 4.0,          // mostly empty bin
    };
    score += class_penalty;

    // Exact-fill bonus (perfect packing)
    if post_residual == 0 {
        score -= 50.0;
    }

    // Modulo coupling: does the leftover match a common item-size residue class?
    // Items 1..=100; leftover divisible by 10 pairs well with typical sizes.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 8.0;
    } else if mod10 <= 3 {
        score += 3.0;
    }

    // Lookahead: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains into this bin: strong reward, scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 12.0 + 8.0 * (1.0 - tight / cap_f);
        } else {
            // leftover smaller than next item: penalty grows with waste
            score += 5.0 + 0.2 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // open bins are congested (few fitting bins) or residuals are fragmented.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let congestion = (fitting_bins_count as f64).recip();
        score += 10.0
            - 15.0 * congestion
            - 10.0 * progress
            - 0.5 * (mean_residual - cap_f * 0.5).abs();
    }

    // Fragmentation pressure: penalize bins whose residual deviates from mean
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Slight preference to fill already-open bins as stream progresses
    score -= 0.01 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are unusable, penalize hard.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny dead space is worst outcome
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 30 {
            score += 10.0;
        }
    } else {
        score -= 40.0; // perfect fill is excellent
    }

    // Reward filling most of the bin (tight fit coupling).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // New-bin candidate: only attractive when item is huge relative to capacity
    // or no real alternative exists; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 25.0; // forced
        } else {
            score += 20.0 - 25.0 * big_item;
        }
    }

    // Last-chance bin: strongly favor using it before opening another.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += 3.0 * pressure * (1.0 - fill_ratio);

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 35.0; // chains a near-perfect follow-up placement
            } else {
                score -= 8.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 5.0; // next item cannot use this gap
        }
    }

    // Prefer bins tighter than the mean residual (consolidation heuristic).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 40.0; // perfect 2-step fit
        } else if post_residual >= next_item_size {
            // slack left after the next item would also fit: mild reward
            score -= 8.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space scaled by how close it is
            let dead = post_residual as f64 / nxt;
            score += 10.0 * dead;
        }
    }

    // Relative-to-mean coupling: bins with less residual than average are precious;
    // penalize wasting them on loose fits, reward filling tight bins.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 12.0 * tightness * (mean_residual / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave awkward residue
    // (very small post_residual that likely can't serve future items) or no fitting bins.
    if bin_residual == bin_capacity {
        let awkward = post_residual > 0 && post_residual < 10;
        let no_fit = fitting_bins_count == 0;
        if awkward || no_fit {
            score -= 30.0;
        } else {
            score += 35.0; // discourage opening new bins when decent fits exist
        }
    }

    // Late-stream bias: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This bin would be consumed in a way blocking the next item.
            score += 8.0;
        }
        // Exact pair fit bonus.
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Last-chance fitting: strongly prefer using the only bin that fits,
    // otherwise residual space may be stranded.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Global residual pressure: if mean residual is high, be picky about fits;
    // if low, accept placements more freely.
    score += 0.15 * (mean_residual - post_residual as f64);

    // Time horizon: early in stream, be more exploratory (favor new bins for
    // large items to build flexible residuals); late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly by default; discount penalty as
        // stream progresses or when existing fits are poor.
        let mut new_bin_penalty = 6.0;
        if item_size > 60 && progress < 0.5 {
            new_bin_penalty -= 3.0;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty = -5.0;
        }
        // Late stream: opening new bins is costly.
        new_bin_penalty += 10.0 * progress;
        score += new_bin_penalty;
    }

    // Slight penalty for placing large items into nearly-full bins when a
    // better candidate might exist elsewhere.
    if item_size as f64 > 0.7 * bin_capacity as f64 && bin_residual < bin_capacity {
        score += 3.0 * (1.0 - fill_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling of post residual with stream progress.
    // Early on (progress ~ 0) we tolerate slack; late (progress ~ 1) we punish dead space.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Reward tight fits via a smooth cubic decay of residual.
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Penalize residuals that are too small to be useful, smoothly.
    score += 20.0 * (1.0 - x) * (1.0 - x) * progress;

    // Lookahead: reward bins whose post residual can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 10.0 * (1.0 - progress);
    }

    // Last-chance bonus: strongly prefer using a nearly exhausted fitting option.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild tie-breaker toward bins below mean residual (consolidate slack).
    score += 0.1 * (pr - mean_residual);

    // Slight penalty for spreading across many bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space.
    // Residuals that are multiples of common item sizes (10, 20, 25, 50) are valuable.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit is ideal
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -6.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize dead space that no plausible item can use: post_residual < 10
    // is unusable dead space (items >= 1, but small items are rare in typical streams;
    // treat <10 as near-dead).
    if pr > 0 && pr < 10 {
        score += 25.0 * (10 - pr) as f64;
    }

    // Fractional capacity logic: post_residual as fraction of capacity.
    let frac = pr as f64 / cap;
    if frac > 0.5 {
        score -= 8.0; // bin still half-full afterwards: fine
    } else if frac < 0.1 {
        score += 10.0 * (0.1 - frac); // nearly-full bin: risk of dead corner
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item can chain into this bin: strong reward
            score -= 15.0;
            // extra reward if next item fills bin exactly or leaves harmonic residual
            let pr2 = pr - next_item_size;
            if pr2 == 0 { score -= 20.0; }
            else if pr2 % 10 == 0 { score -= 5.0; }
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            score += 3.0 * ((next_item_size - pr) as f64).min(30.0);
        }
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when current
    // fits are poor. Give the empty bin a moderate baseline score.
    if bin_residual == bin_capacity {
        score = 55.0
            + 0.05 * open_bins_count as f64
            + (item_size as f64) * 0.15;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin is attractive
        }
        if step_index as f64 / total_items as f64 > 0.9 {
            score += 10.0; // late in stream: avoid opening bins unnecessarily
        }
    }

    // Slight preference for tighter bins when many bins fit the item
    // (best-fit bias scaled by bin congestion).
    score += (bin_residual - item_size) as f64 * 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste. Penalize them quadratically.
    let dead_threshold = 10.0; // smallest item footprint baseline
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64).powi(2) * 3.0;
    }

    // Reward near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize leaving a gap that next_item_size cannot use (wasted lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64;
    }
    // Reward reserving exactly enough space for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is a hopeless dead gap).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= dead_threshold as u32 || post_residual == 0 {
            score -= 30.0;
        }
    }

    // New-bin candidate handling: only attractive when all existing fits are bad.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, modulated by congestion and
        // how fragmented current residuals are.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 45.0 + open_bins_count as f64 * 0.8 + fragmentation * 0.3;
        // If the current bin would leave a dead gap, opening fresh becomes better.
        if bin_residual >= item_size && post_residual < dead_threshold as u32 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening bins for marginal gains.
        score += 15.0 * progress;
    }

    // Slight pull toward bins whose residual is close to the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / 10.0).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the resulting residual.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0;
        } else if diff <= 5 {
            score -= 30.0;
        } else if diff <= 15 {
            score -= 10.0;
        } else {
            // Penalize residuals that leave awkward gaps relative to the next item.
            score += diff as f64 * 0.15;
        }
        // Extra reward if next item fits exactly AND this is a tight fit overall.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size == 0 {
        // Last item: prefer the fullest packing (smallest post_residual).
        score -= 10.0;
    }

    // Penalize bins that are much emptier than the mean (wasteful placement).
    if (bin_residual as f64) > mean_residual * 1.3 && bin_residual != bin_capacity {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, penalize large dead space nonlinearly.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead * dead;

    // Strong reward for exact/near-exact fit.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // partial reward proportional to how well next item fills the leftover
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving a residual that is
            // just barely too small (worst kind of dead space)
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 15.0;
            }
        }
    } else {
        // Last item: prefer fullest packing possible.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item is large relative to capacity or existing bins are fragmented.
    if bin_residual == bin_capacity {
        // cost of opening a new bin grows with open bins and with available fits
        score += 25.0 + 3.0 * open_bins_count as f64 + 8.0 * fitting_bins_count as f64;
        // discount new bin early in the stream (plenty of future items to fill it)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // if item is huge, a fresh bin is fine
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    // Global fragmentation pressure: if mean residual is high, prefer packing
    // into existing bins rather than spreading.
    if mean_residual > post_residual as f64 {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // Prefer bins whose residual is close to item_size (snug fit) beyond raw post_residual.
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * snug;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills; later, tolerate larger residuals.
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let progress_weight = 0.5 + progress;
    score += progress_weight * norm_pr * norm_pr * bin_capacity as f64;

    // Smooth interaction: residual above mean is penalized quadratically.
    let diff = pr - mean_residual;
    score += 0.05 * diff * diff / bin_capacity as f64;

    // Reward tight fit via cubic smooth term on (1 - normalized residual).
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead coupling: bonus if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let fits = (post_residual as f64) >= (next_item_size as f64);
        if fits {
            score -= 4.0;
        } else {
            score += 0.02 * (next_item_size as f64 - pr).max(0.0);
        }
    }

    // Last-chance bonus: smooth reward scaled by scarcity of fitting bins.
    if fitting_bins_count <= 1 {
        score -= 6.0;
    }

    // Mild penalty for proliferating open bins, smoothed by progress.
    score += (open_bins_count as f64) * (0.1 + 0.2 * progress);

    // New-bin candidate: penalize slightly so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual: residues modulo small divisors ----
    // Residuals that are multiples of 5 or 10 are "harmonic" — they pair well
    // with future items drawn from typical integer streams.
    let pr = post_residual;
    let harmonic5 = (pr % 5 == 0) as i32;
    let harmonic10 = (pr % 10 == 0) as i32;
    let harmonic25 = (pr % 25 == 0) as i32;
    score -= 6.0 * harmonic10 as f64;
    score -= 3.0 * harmonic5 as f64;
    score -= 2.0 * harmonic25 as f64;

    // Dead-space penalty: post_residual in awkward bands (1..9 or 11..19 style
    // non-harmonic slivers) is nearly unusable for items >= 10.
    if pr > 0 && pr < 10 {
        score += 40.0; // pure dead space
    } else if pr >= 10 && pr < 20 && pr % 5 != 0 {
        score += 8.0;
    }

    // ---- Integer-division threshold on post_residual ----
    // Classify residual into capacity fractions: /4, /2, /3/4.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let threeq = 3 * quarter;
    if pr >= threeq {
        score -= 10.0; // bin still very roomy, fine to keep filling
    } else if pr >= half {
        score -= 5.0;
    } else if pr >= quarter {
        score += 2.0;
    }

    // ---- Coupling with next_item_size (lookahead, k=2) ----
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item also fits here: strong reward for keeping this bin.
            score -= 15.0 + 0.2 * next_item_size as f64;
            // Extra reward if post_residual after BOTH items stays harmonic.
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 8.0; }
            else if pr2 % 5 == 0 { score -= 4.0; }
            if pr2 > 0 && pr2 < 10 { score += 10.0; }
        } else {
            // Next item won't fit: penalize if this placement strands the bin
            // with a small non-harmonic residue.
            if pr > 0 && pr < next_item_size {
                score += 0.3 * (next_item_size - pr) as f64;
            }
        }
    } else {
        // Last item: prefer tightest packing, ignore lookahead terms.
        score += 0.0;
    }

    // ---- Last-chance bin: if this is the only fitting bin, avoid opening a new one ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // and the current item is large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < 0.5 * bin_capacity as f64;
        if crowded && item_size > threeq {
            score -= 12.0 * progress;
        } else {
            score += 30.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Mild tie-break: prefer bins with residual close to item size (tight fit).
    score += 0.1 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Dead-space penalty: gaps too small to be useful later.
    // Threshold scales with typical item size (assume >= 10, use item as proxy).
    if post > 0.0 && post < item * 0.35 {
        score += 60.0 * (1.0 - post / (item * 0.35));
    }

    // Reward tight fits (small post_residual overall).
    score -= 40.0 * (1.0 - post / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage scattering across many bins when
    // post_residual is wasteful; encourage filling existing bins.
    score += (open_bins_count as f64) * 0.8 * (post / cap);

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && (next_item_size as f64) == post {
        score -= 70.0;
    } else if next_item_size > 0 && (next_item_size as f64) > post {
        // next item can't use this gap -> dead space risk
        score += 12.0;
    }

    // New-bin candidate: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; pressure grows with open bins
        // being low (early) and shrinks when open bins are crowded.
        score += 25.0 + (open_bins_count as f64) * 1.5;
        // But if the item is large, opening fresh is fine.
        if item > cap * 0.6 {
            score -= 30.0;
        }
    }

    // Slight preference to use bins with below-average residual (filler bins).
    if bin_residual != bin_capacity {
        score += 5.0 * ((bin_residual as f64) - mean_residual) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
