pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can't fit even the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward strongly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if next_item_size >= 10 && post_residual < 10 {
            score += 8.0; // post-residual likely dead space for next item
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with below-average residual (conserving large residual bins).
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap;

    // New-bin candidate handling: only attractive late in stream or when few bins fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 - 8.0 * progress; // cheaper to open new bins early
        if fitting_bins_count > 0 {
            score += 10.0; // discourage abandoning usable open bins
        }
    }

    // Mild penalty for many open bins (fragmentation control).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly super-linear to punish dead space
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Smooth non-linear coupling with stream progress:
    // early on, prefer compacting (low post_residual weighted); later, prefer
    // leaving room shaped like the lookahead item.
    let prog_curve = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 40.0 * prog_curve * norm_pr * (1.0 - norm_pr);

    // Lookahead shaping: reward post_residual close to next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score += 30.0 * diff * diff * cap;
        // bonus if next item fits exactly
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // Slight penalty when this bin is much tighter than average (fragmentation)
    let mr = mean_residual;
    let spread = (pr - mr) / cap;
    score += 6.0 * spread * spread * cap;

    // New-bin candidate: keep it neutral-ish unless open bins are wasteful
    if bin_residual == bin_capacity {
        score = pr + 10.0 + 20.0 * progress - 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small,
    // "dead" classes are penalized; residuals that match common item sizes are rewarded.
    let cap = bin_capacity as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space class: residual < 10 (below minimum item size) is wasted unless 0.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic classes of capacity: residual near halves/quarters of capacity.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    let dr = post_residual as f64;
    if (dr - half).abs() < 3.0 {
        score -= 15.0; // residual ~50 is highly reusable
    } else if (dr - quarter).abs() < 3.0 {
        score -= 7.0;
    }

    // Integer-division threshold: classify residual into buckets of 10.
    let bucket = post_residual / 10;
    score -= (bucket as f64) * 2.0; // prefer larger residuals mildly, modulated below

    // Lookahead coupling: reward when next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: how tightly?
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 120.0; // chains a perfect fit
            } else if slack < 10 {
                score -= 40.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: penalize if this was the only fitting bin
            if fitting_bins_count == 1 {
                score += 25.0;
            }
            score += 8.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless post residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 {
            score -= 80.0;
        } else if post_residual == 0 {
            score -= 200.0;
        }
    }

    // New-bin candidate: make it attractive only when open bins are very full
    // or this item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 5.0 {
            score -= 30.0; // no good existing home
        } else {
            score += 40.0 + mean_gap; // prefer existing bins with room
        }
        // early stream: slightly discourage spreading into many bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Mild penalty when many bins are open and this bin is far below mean residual
    // (keeps residuals balanced, avoids many near-empty bins).
    if open_bins_count > 3 {
        let dev = mean_residual - dr;
        if dev > 20.0 {
            score += dev * 0.3;
        }
    }

    // Modulo-arithmetic bonus: residuals divisible by 10 align with typical item grids.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps too small to hold the smallest
    // plausible item (size 1..~10) are worthless. Penalize them hard.
    let tiny_gap = post > 0.0 && post < 10.0;
    if tiny_gap {
        score += 40.0 * (1.0 - post / 10.0); // smaller gap => worse
    }
    // Moderate dead space (10..25) is also often unusable given item range.
    if post >= 10.0 && post < 25.0 {
        score += 12.0 * (1.0 - (post - 10.0) / 15.0);
    }

    // Reward near-perfect fills.
    if post == 0.0 {
        score -= 30.0;
    } else if post <= 5.0 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // it over opening a new bin (unless it creates a tiny dead gap).
    if fitting_bins_count == 1 && bin_residual != bin_capacity && !tiny_gap {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 - 0.5 * progress);
    score += pressure * 0.6;

    // New-bin candidate (residual == capacity): it leaves post == capacity -
    // item, which is large, so raw score is high. Allow it to win only when
    // placing elsewhere would strand a tiny gap or the item is huge.
    if bin_residual == bin_capacity {
        let huge_item = (item_size as f64) > 0.8 * cap;
        if huge_item {
            score -= 20.0; // big items deserve fresh bins
        } else {
            score += 8.0; // mild bias against opening bins for small items
        }
    }

    // Lookahead: if the next item fits the post-residual exactly-ish,
    // reward keeping this pairing alive.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt && post - nxt < 10.0 {
            score -= 10.0;
        }
        if post < nxt && post > 0.0 && post < 10.0 {
            score += 10.0; // next item cannot use this sliver
        }
    }

    // Slight preference for bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with superlinear penalty.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // --- 2-step lookahead: reward post_residual that matches next_item_size ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect lookahead match: next item exactly fills this bin afterwards.
        if post_residual as f64 == nxt {
            score -= 60.0; // chain completion: two items perfectly packed
        } else if post_residual >= next_item_size {
            // Next item can also go here later; reward closeness of the match.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: dead space penalty grows
            // with how badly it misses the next item.
            score += 10.0 * (diff / 100.0);
        }
        // If the next item cannot fit anywhere else and this bin is its only
        // future home, strongly protect a compatible residual.
        if post_residual >= next_item_size && fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current residual
    // is unusably small (fragmented) or the stream is nearly done.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = bin_residual as f64 - item_size as f64; // residual after placing here
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open a new bin only when existing residuals are tiny/fragmented
        // and the waste would be small, or at the very end of the stream.
        if fragmentation > 0.5 && waste as f64 <= 0.35 * bin_capacity as f64 {
            score -= 30.0;
        } else {
            score += 45.0 + 30.0 * (1.0 - progress);
        }
    }

    // Mild preference for bins with below-mean residual (consolidate fullness).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Small bonus for very tight absolute fits.
    if post_residual <= 5 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly favor bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + 6.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, use it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more willing to spread (open bins);
    // late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 && mean_residual > (item_size as f64) {
        score -= 3.0 * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // Mild penalty for opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        let new_bin_cost = 20.0 * (1.0 - progress);
        score += new_bin_cost;
        // But if the item is large relative to capacity, opening fresh may be wise.
        if item_size as f64 > 0.6 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, damped by progress (late stream => tighter packing)
    let mut score = pr * (1.0 - 0.5 * progress);

    // Non-linear polynomial coupling of normalized post-residual with progress
    let t = progress;
    let coupling = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 + 2.0 * t);
    score += 30.0 * coupling;

    // Penalize post-residual that cannot fit next item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (1.0 - pr / nxt) * (1.0 + t);
        } else {
            // Reward leaving room for the lookahead item
            score -= 4.0 * (1.0 - (pr - nxt) / cap) * (1.0 - t);
        }
    }

    // Last-chance bonus: only one fitting bin => strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty for very full bins early (keep flexibility), reward later
    score -= (1.0 - norm_pr) * (2.0 * t - 1.0);

    // Slight preference to spread across many open bins early
    score += 0.3 * open_bins_count as f64 * (1.0 - t);

    // Deviation from mean residual: prefer bins near the mean (balanced use)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual falls into
    // "small residue" classes (post_residual % 10 near 0) are hard to reuse.
    let residue_class = post_residual % 10;
    let class_penalty = match residue_class {
        0 => -6.0,                       // perfectly divisible leftover, reusable
        1 | 2 => 4.0,                    // awkward slivers
        3 | 4 => 1.5,
        8 | 9 => 2.0,                    // nearly full bin, low waste but dead space
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual: leftover smaller than the
    // minimum plausible item is pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable dead space
    } else if post_residual <= 20 {
        score += (20 - post_residual) as f64 * 0.5;
    }

    // Perfect-fill bonus via capacity fractions
    if post_residual == 0 {
        score -= 30.0;
    } else if bin_capacity % post_residual == 0 && post_residual <= bin_capacity / 2 {
        // leftover can be tiled by equal items
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit the post residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain fill
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 - (slack as f64).min(10.0) * 0.4;
            if slack % 10 == 0 {
                score -= 3.0; // harmonic alignment
            }
        } else {
            score += 6.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bins get a moderate default score,
    // beaten only when this bin is a genuinely bad host.
    if bin_residual == bin_capacity {
        score = cap * 0.55 - (item_size as f64) * 0.15;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big items pair well in fresh bins
        }
    }

    // Mild progression term: early on, consolidate; late, prefer tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let dr = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness reward (from best heuristic): quadratic in fill.
    let tightness = 1.0 - dr / cap;
    score -= 25.0 * tightness * tightness;

    // Dead-space class: residuals too small to ever be reused are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Harmonic classes of capacity: residual near halves/quarters is reusable.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (dr - half).abs() < 3.0 {
        score -= 15.0;
    } else if (dr - quarter).abs() < 3.0 {
        score -= 7.0;
    }

    // Modulo bonus: residuals divisible by 10 align with typical item grids.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: reward when next item fits post residual tightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 120.0;
