    // Mild penalty when bin is far from mean residual (diversity of residual sizes)
    score += 0.05 * (pr - mean_residual).abs();

    // Slight preference for filling existing bins vs opening new ones
    score += 0.01 * open_bins_count as f64;

    score
}

