    score -= 30.0 * tightness * tightness;

    // Harmonic classes of capacity residual.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (dr - half).abs() < 3.0 {
        score -= 15.0;
    } else if (dr - quarter).abs() < 3.0 {
        score -= 7.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 130.0;
            } else if slack < 10 {
                score -= 45.0;
            } else {
                score -= 12.0;
            }
        } else {
            if fitting_bins_count == 1 {
                score += 25.0;
            }
            score += 8.0;
        }
