pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: this bin's post residual
    // exactly accommodates the next item (perfect chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near matches (post_residual can still hold next item with little waste)
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack / 10.0);
    }
    // Penalize if next item cannot fit here (dead space for the lookahead)
    else if next_item_size > 0 {
        score += 15.0;
    }

    // Penalize creating tiny unusable residuals (dead space), scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (2.0 + 3.0 * progress);
    }

    // Prefer bins that are tighter than average (best-fit style) —
    // subtract relative to mean residual.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless it offers a genuinely
    // better 2-step plan. Penalize by remaining stream length and open bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * (open_bins_count as f64).sqrt() + 20.0 * (1.0 - progress);
        // But allow opening a fresh bin when the next item is large enough to
        // pair with the current one in a fresh bin.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && post_residual == next_item_size {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64) ;
    score -= 34.0 * tightness * tightness ;

    // residual dead-space bands (refined)
    if post_residual > 0 && post_residual < 8 {
        score += 30.0 ;
    } else if post_residual >= 8 && post_residual < 18 {
        score += 12.0 ;
    }

    // lookahead: prefer bins that can also host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 22.0 ;
            if post_residual == next_item_size {
                score -= 14.0 ;
            }
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 9.0 ;
        }
        if item_size + next_item_size == bin_residual {
            score -= 17.0 ;
        }
        // chain lookahead: penalize leaving a gap that neither current nor next item can use
        if post_residual > 0 && post_residual < next_item_size && post_residual < item_size.min(next_item_size) {
            score += 6.0 ;
        }
    }

    // sole fitting bin: strong reward, scaled by how tight the fit is
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        let slack = (bin_residual - item_size) as f64 ;
        score -= 42.0 - 0.35 * slack ;
    }

    // fill pressure with mild saturation on open bin count
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64 ;
    let nb = (open_bins_count as f64).ln().max(1.0) ;
    score -= 14.0 * fill_ratio * nb ;

    // deviation from mean residual: reward pulling residuals toward the mean
    score += 0.20 * (mean_residual - post_residual as f64) ;

    // mild bonus for very full bins late in the stream
    if post_residual == 0 {
        score -= 10.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (low post-residual gets extra bonus, non-linear).
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits the post-residual well, reward.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let waste_after_next = post - next_item_size as f64;
        score -= 8.0 * (1.0 - waste_after_next / cap);
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize slightly if we leave a big hole.
        score += 0.05 * post;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer bins where the item fits most snugly (already via post).
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Penalize creating dead space below the minimum item size (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Global state: many open bins with high mean residual -> favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > post {
        score += 0.03 * (mean_residual - post) * (1.0 - progress);
    }

    // Late in stream: consolidate, avoid opening new bins.
    if bin_residual < bin_capacity {
        score -= 3.0 * progress;
    } else {
        // New-bin candidate: penalize more as stream progresses.
        score += 4.0 * progress + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, scaled mildly by stream progress
    let mut score = pr * (0.8 + 0.4 * progress);

    // Non-linear polynomial coupling of post_residual with progress:
    // tight fits (small norm_pr) are increasingly rewarded as stream advances
    let tight = 1.0 - norm_pr;
    score -= 30.0 * tight * tight * (0.3 + 0.7 * progress);

    // Penalize dead space that is too small for typical future items (smooth gate)
    let dead = norm_pr * (1.0 - norm_pr); // peaks mid-range
    score -= 15.0 * dead;

    // Lookahead: if next item fits the post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 + 8.0 * (1.0 - progress);
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for spreading across many open bins early
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean (smooth balance)
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline with slight late-stream penalty
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) + 0.5 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let dr = post_residual as f64;

    // Tightness reward: prefer bins that become nearly full.
    let tightness = 1.0 - (dr / cap);
    score -= 34.0 * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes.
    if post_residual > 0 && post_residual < 10 {
        score += 27.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 11.0;
    }

    // Harmonic classes of capacity.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (dr - half).abs() < 3.0 {
        score -= 15.0;
    } else if (dr - quarter).abs() < 3.0 {
        score -= 7.0;
    }

    // Lookahead coupling: reward when next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0;
            if slack == 0 {
                score -= 120.0;
            } else if slack < 10 {
                score -= 40.0;
            }
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 8.0;
        }
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Last-chance logic: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual == 0 {
            score -= 200.0;
        } else if post_residual >= 10 {
            score -= 42.0;
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 5.0 {
            score -= 30.0;
        } else {
            score += 40.0 + mean_gap;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Balance penalty for far-below-mean residuals when many bins open.
    if open_bins_count > 3 {
        let dev = mean_residual - dr;
        if dev > 20.0 {
            score += dev * 0.3;
        }
    }

    // Fill-based pressure to prefer fuller bins as the stream grows.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 13.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Residual-mean alignment.
    score += 0.18 * (mean_residual - dr);

    // Modulo-arithmetic bonus.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues in the low classes
    // (small dead space) are most valuable. Use integer division thresholds
    // on post_residual to build 4 harmonic classes.
    let post = post_residual as f64;
    let class = (post / 25.0).floor().min(3.0); // 0..3
    score -= (3.0 - class) * 12.0;

    // Perfect fit reward (post_residual near zero or a harmonic fraction of capacity)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Residue congruence: leftover that is a "nice" remainder (divisible by 10)
    // is more likely reusable by future items drawn from typical granularities.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Penalize awkward remainders (mod 10 in 1..=3) which are near-dead space.
    let awkward = post_residual % 10;
    if awkward >= 1 && awkward <= 3 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward closeness of next item to leftover (harmonic matching)
            score -= 20.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item won't fit here; leftover must stand alone, penalize big leftovers
            score += 6.0 * (post / 25.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: empty bin should only win when all open bins are poor fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened when many items remain
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 - 10.0 * progress;
        // if no open bin fits, new bin is relatively attractive
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Prefer tighter bins relative to the mean residual across open bins.
    score -= (mean_residual - post) * 0.3;

    // Mild preference for filling large items into tight bins early in the stream.
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score -= tightness * (item_size as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let dr = post_residual as f64;

    // Tightness reward: smaller post_residual (relative to capacity) is better.
    let tightness = 1.0 - (dr / cap);
    score -= 34.0 * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: small residuals are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Harmonic classes of capacity: residual near halves/quarters of capacity.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (dr - half).abs() < 3.0 {
        score -= 15.0;
    } else if (dr - quarter).abs() < 3.0 {
        score -= 7.0;
    }

    // Bucket preference: mildly prefer larger residuals.
    let bucket = post_residual / 10;
    score -= (bucket as f64) * 2.0;

    // Lookahead coupling: reward when next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 130.0;
            } else if slack < 10 {
                score -= 45.0;
            } else {
                score -= 12.0;
            }
        } else {
            // next item won't fit here: penalize if this was the only fitting bin
            if fitting_bins_count == 1 {
                score += 25.0;
            }
            // but reward if the current bin_residual would have fit the next item
            if bin_residual >= next_item_size && post_residual < next_item_size {
                score += 8.0;
            }
            score += 8.0;
        }
        // two-item exact match: item + next exactly fills the bin
        if item_size as u64 + next_item_size as u64 == bin_residual as u64 {
            score -= 18.0;
        }
    }

    // Last-chance logic: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 {
            score -= 80.0;
        } else if post_residual == 0 {
            score -= 200.0;
        }
    }

    // New-bin candidate: attractive only when open bins lack room for the item.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 5.0 {
            score -= 30.0;
        } else {
            score += 40.0 + mean_gap;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Balance pressure: penalize bins far below mean residual when many bins open.
    if open_bins_count > 3 {
        let dev = mean_residual - dr;
        if dev > 20.0 {
            score += dev * 0.3;
        }
    }

    // Fill-ratio term: prefer bins that are already heavily filled,
    // scaled by log of open bins count.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 13.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Mean-residual alignment: reward bins whose post residual tracks the mean.
    score += 0.18 * (mean_residual - dr);

    // Grid alignment bonus.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // "Awkward gap" zone: likely dead space for most item sizes.
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (near-perfect packing) superlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow a new bin if this fit would create dead space.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * post_residual as f64 * 0.3;

    // Lookahead: if next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot use this residual -> residual more likely dead.
            score += 8.0;
        }
    }

    // New-bin candidate handling: an empty bin is a safe reservoir; prefer it
    // only when this placement would leave a bad gap and other bins exist.
    if bin_residual == bin_capacity {
        // Neutral baseline slightly worse than a perfect fit, better than dead space.
        score = 20.0 + pressure * 15.0;
        // Early in stream, opening bins is cheap-ish; late, conserve.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= item_size {
            score -= 10.0;
        }
    }

    score
}

