            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize if we leave awkward dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.35 * dead; // dead space that blocks the known next item
            }
        }
    } else {
        // last item: just minimize post_residual (already base term)
    }

    // Compare residual against mean residual of open bins: prefer bins below/around mean
    // to balance residual distribution, unless it's a tight fit.
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // gives a decent fit. Penalize the empty-bin candidate mildly, escalating with
    // stream progress (late in the stream, consolidating matters more).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 + 20.0 * progress;
