pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 36.0 * tightness * tightness;

    // Dead-space avoidance: tiny unusable gaps are waste.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 30.0 + (dead_threshold - post_residual) as f64 * 2.0;
    } else if post_residual >= dead_threshold && post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: reward bins whose leftover can serve the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 22.0;
            if post_residual == next_item_size {
                score -= 12.0;
            }
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 8.0;
        }
        if item_size + next_item_size == bin_residual {
            score -= 16.0;
        }
        // Chain lookahead: bin can hold item now and next item exactly later.
        if post_residual >= item_size + next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        if post_residual == 0 || post_residual >= dead_threshold {
            score -= 42.0;
        }
    }

    // Prefer fuller bins, amplified by number of open bins (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 13.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Open-bin pressure: mild, scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.8 + 1.2 * progress);

    // Pull toward mean residual (balanced packing), signed to favor slightly-above-mean leftovers.
    score += 0.18 * (mean_residual - post_residual as f64);

    // New-bin candidate: high baseline cost; only attractive when existing
    // fits would leave dead gaps or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.6 + 20.0 * progress;
        if bin_residual >= item_size && post_residual < dead_threshold {
            score -= 25.0;
        }
        // If no open bin fits well, opening fresh is reasonable.
        if fitting_bins_count == 0 && item_size > mean_residual as u32 {
            score -= 15.0;
        }
        // Never open a new bin when a perfect fit exists elsewhere.
        if fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

