    // NEW: fine-grained dead-space penalty scaled by item size.
    // Large items leaving tiny residuals are worse than small items doing so.
    if post_residual > 0 && post_residual < item_size {
        score += 0.4 * (item_size - post_residual) as f64;
    }

    // NEW: lookahead chain bonus — if next item perfectly fits post residual
    // AND the one after that tendency is unknown, still favor near-exact chains
