    if next_item_size > 0 && next_item_size == post_residual && open_bins_count <= 4 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial coupling to stream progress.
    // Early in the stream, keep bins tight (minimize post_residual strongly);
    // late in the stream, allow larger residuals since bins are near-closed.
    let mut score = pr * (1.0 + 0.5 * progress * progress) - 20.0 * norm_pr * (1.0 - progress);

    // Penalize tiny dead space that is hard to fill (quadratic valley near small residuals).
    let dead = norm_pr;
    score += 8.0 * dead * (1.0 - dead) * (1.0 - dead);

    // Reward near-perfect fits (small post_residual) with a smooth exponential bonus.
    score -= 15.0 * (-pr / 12.0).exp();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack_after_next = pr - nxt;
            score -= 12.0 * (-slack_after_next / 10.0).exp();
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Compare against mean residual: placing into a below-average-residual bin
    // (tight bin) preserves loose bins for future awkward items.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New empty bin candidate: neutral-ish baseline, slightly penalized so we
    // prefer existing bins unless fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
    }

    // Mild regularization by number of open bins to discourage bin proliferation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
