pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (base 10) ---
    // Residuals that are multiples of 10 are "clean": they pair perfectly with
    // whole classes of future items; reward them.
    if post_residual % 10 == 0 {
        score -= 6.0;
        if post_residual == 0 {
            score -= 14.0; // perfect fit, best possible outcome
        }
