    match post_residual / 10 {
        0 => score += 12.0,      // 0-9: sliver risk (offset by clean-class bonus)
        1 => score -= 4.0,       // 10-19: tight but reusable
        2 | 3 => score -= 8.0,   // 20-39: sweet spot for medium items
        4 | 5 => score -= 2.0,   // 40-59: acceptable
        _ => {}                  // 60+: mostly empty bin, weak use of space
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;       // next item exactly fills this bin
        } else if next_item_size <= post_residual {
            // harmonic match: next item's residue class also divides cleanly
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's remainder; if remainder is a
            // sliver class, the waste is locked in
            if post_residual >= 1 && post_residual <= 9 {
                score += 10.0;
            }
        }
    }

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 {
        // This is the only bin that fits the item; using it avoids opening a
        // new bin. Strong reward unless it creates a terrible sliver.
        if !(post_residual >= 1 && post_residual <= 9) {
            score -= 16.0;
        } else {
            score -= 4.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin: post_residual = capacity - item_size.
        // Penalize so it only wins when all open fits are poor, but reward
        // opening for large items whose placement would otherwise strand space.
        score += 30.0;
        let frac = item_size as f64 / bin_capacity as f64;
        if frac >= 0.7 {
            score -= 12.0; // large items justify fresh bins
        }
        if next_item_size > 0 && next_item_size <= post_residual {
