        score -= 12.0;
    } else if post_residual >= 4 && post_residual < 10 {
        score += 32.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Harmonic classes of capacity: residual near halves/quarters of capacity.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (dr - half).abs() < 3.0 {
        score -= 15.0;
    } else if (dr - quarter).abs() < 3.0 {
        score -= 7.0;
    }

