pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let dr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tightness reward: smaller post_residual (relative to capacity) is better.
    let tightness = 1.0 - (dr / cap);
    score -= 42.0 * tightness * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: tiny residuals are nearly perfect, small ones are wasted.
    if post_residual > 0 && post_residual < 4 {
        score -= 14.0;
    } else if post_residual >= 4 && post_residual < 10 {
        score += 32.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Harmonic classes of capacity: residual near halves/quarters of capacity.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (dr - half).abs() < 3.0 {
        score -= 15.0;
    } else if (dr - quarter).abs() < 3.0 {
        score -= 7.0;
    }

    // Lookahead coupling: reward when next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 175.0;
            } else if slack < 8 {
                score -= 60.0;
            } else if slack < 20 {
                score -= 32.0;
            } else {
                score -= 15.0;
            }
            let after_next = post_residual - next_item_size;
            // chain lookahead: bin can host next item AND another like it
            if after_next >= next_item_size {
                score -= 11.0;
            }
            // dead-space avoidance: penalize slack too small for the mean item
            if slack > 0 && (slack as f64) < mean_residual * 0.3 {
                score += 7.0 - 3.0 * progress;
            }
            // reward slack that fits the current item size almost exactly (perfect chain)
            if slack >= item_size && slack.saturating_sub(item_size) < 6 {
                score -= 12.0;
            }
            // penalize slack too large relative to capacity (wasted interior space)
            if (slack as f64) > cap * 0.45 {
                score += 4.0 * ((slack as f64 / cap) - 0.45);
            }
            // deep chain lookahead: residual can host a third consecutive item
            let after_three = (after_next as i64) - (next_item_size as i64);
            if after_three >= 0 && (after_three as u64) <= (item_size as u64 + next_item_size as u64) {
                score -= 9.0;
            }
            // avoid leaving a tiny unusable sliver
            if after_next >= 1 && after_next <= 5 {
                score -= 14.0;
            }
            // pair-fit shaping
            let pair_fit = (post_residual - next_item_size) as f64 / cap;
            score -= 9.0 * (1.0 - pair_fit);
        } else {
            if fitting_bins_count == 1 {
                score += 30.0;
            }
            if bin_residual >= next_item_size && post_residual < next_item_size {
                score += 10.0;
            }
            score += 8.0;
        }
        // stranded-space penalty: post residual too small for the next item
        if post_residual > 0 && post_residual < next_item_size {
            let stranded = next_item_size as f64 - dr;
            score += 0.40 * stranded;
            if fitting_bins_count <= 2 {
                score += 6.0;
            }
            // anti-fragmentation: sliver the next item cannot even half-use
            if (post_residual as f64) < (next_item_size as f64) * 0.5 {
                score += 5.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
            }
        }
        // two-item exact match: item + next exactly fills the bin
        if item_size as u64 + next_item_size as u64 == bin_residual as u64 {
            score -= 26.0;
        }
        // waste ratio lookahead
        if post_residual > 0 {
            let waste = dr / next_item_size as f64;
            if waste >= 2.0 {
                score += 6.0 * (waste - 2.0).min(10.0);
            }
        }
        // post-residual chain shaping
        if post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next >= 1 && after_next <= 5 {
                score -= 15.0;
            }
            if after_next > 0 && (after_next as f64) < mean_residual * 0.35 {
                score += 9.0;
            }
