    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from mean in a useful way (below-mean residual = tighter bin).
    score += 0.3 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream
        // or when existing bins would leave big dead space.
