    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize unusable dead space quadratically; perfect fits (0 residual) heavily rewarded.
    score += 40.0 * frac * frac;

    // Integer-division thresholds: residuals <= 10 are essentially unusable
    // (min item size is 1, but statistically small residuals attract small items poorly).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual <= 20 && post_residual > 10 {
        score += 8.0;
