    // Modulo arithmetic on post_residual: residuals that are "harmonic" with
    // common item sizes (multiples of 5, 10) are more likely to be filled later.
    let harmonic_bonus = if post_residual % 10 == 0 {
        12.0
    } else if post_residual % 5 == 0 {
        6.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further residual: mild reward scaled by tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * tight;
        } else {
            // next item cannot use this bin's leftover: penalize proportional to leftover size
            score += 5.0 * frac;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * bin_residual as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (poor fits everywhere) or many bins are open.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its post_residual == capacity, already high.
        // Reward opening new bins when the stream is early or many bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // If mean residual is small (open bins are full-ish), new bin is fine.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 5.0;
    } else {
        // Prefer filling existing bins when they are relatively full compared to mean.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Slight preference for tighter fits overall.
    score -= (bin_residual - post_residual) as f64 * 0.05;

    score
}

