    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can host the next item (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            // Perfect two-item packing: post residual exactly consumed next step.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits with leftover slack; reward proportional to snugness.
            let slack = post_residual as f64 - nxt;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize dead space relative to next item size.
            let dead = nxt - post_residual as f64;
            score += 0.5 * dead;
        }

        // Two-step coupling: if post_residual is small AND next item is large,
        // this bin becomes dead weight soon; penalize.
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: purely minimize post_residual (already done) plus tie-break.
        score += 0.0;
    }

    // Compare against mean residual: bins far below mean are "tight" and
    // precious — using them is good if the item fits snugly.
    let tightness = mean_residual - post_residual as f64;
    if tightness > 0.0 {
        score -= 0.3 * tightness; // bin becomes tighter than average: good
    } else {
        score += 0.2 * (-tightness); // bin stays loose: mild penalty
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize opening a new bin unless item is huge
    // relative to capacity or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        // New bins are attractive for large items early on, or when many
        // open bins exist but none fits well (fitting_bins_count small).
        score += 55.0 - 45.0 * big_item - 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 70.0; // nothing else fits: new bin is fine
        }
    }

    // Mild preference to keep number of open bins from exploding.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let dr = post_residual as f64;

    // Tightness reward (strengthened, cubic).
    let tightness = 1.0 - (dr / cap);
    score -= 42.0 * tightness * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: tiny residuals are excellent, small-but-not-tiny are wasted.
    if post_residual > 0 && post_residual < 4 {
        score -= 14.0;
    } else if post_residual >= 4 && post_residual < 10 {
        score += 32.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Harmonic classes of capacity.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (dr - half).abs() < 3.0 {
        score -= 15.0;
    } else if (dr - quarter).abs() < 3.0 {
        score -= 7.0;
    }

    // Bucket preference: mildly prefer larger residuals.
    let bucket = post_residual / 10;
    score -= (bucket as f64) * 2.5;

    // Lookahead coupling.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 175.0;
            } else if slack < 8 {
                score -= 60.0;
            } else if slack < 20 {
                score -= 32.0;
            } else {
                score -= 15.0;
            }
            let after_next = slack;
            // Bin can host next item AND the one after it (two-step chain).
            if after_next >= next_item_size {
                score -= 11.0;
            }
            // Dead-space avoidance: slack too small for the mean item, scaled by progress.
            if (after_next as f64) < mean_residual * 0.3 {
                let progress = step_index as f64 / total_items.max(1) as f64;
                score += 7.0 - 3.0 * progress;
            }
            // Reward slack that still fits the item after next exactly (perfect chain).
            if after_next >= item_size as u32 && after_next.saturating_sub(item_size) < 6 {
                score -= 12.0;
            }
            // Penalize slack too large relative to capacity (wasted interior space).
            if (after_next as f64) > cap * 0.45 {
                score += 4.0 * ((after_next as f64 / cap) - 0.45);
            }
            // Prefer slack matching mean residual (predictable future fits).
            if after_next > 0 && (after_next as f64 - mean_residual).abs() < 4.0 {
                score -= 8.0;
            }
        } else {
            if fitting_bins_count == 1 {
                score += 30.0;
            }
            if bin_residual >= next_item_size && post_residual < next_item_size {
                score += 10.0;
            }
            score += 8.0;
        }
        // Two-item exact match.
        if item_size as u64 + next_item_size as u64 == bin_residual as u64 {
            score -= 26.0;
        }
        // Waste-vs-next-item coupling.
        if post_residual > 0 {
            let waste = post_residual as f64 / next_item_size as f64;
            if waste >= 2.0 {
                score += 6.0 * (waste - 2.0).min(10.0);
            }
        }
        // Stranded sliver: post residual cannot host next item.
        if post_residual > 0 && post_residual < next_item_size {
            let stranded = next_item_size as f64 - dr;
            score += 0.40 * stranded;
            if fitting_bins_count <= 2 {
