            let after_three = slack as i64 - next_item_size as i64 - item_size as i64;
            if after_three >= 0 && (after_three as u64) <= next_item_size as u64 {
                score -= 7.0;
            }
            // Penalize overly large slack (wasted interior space).
            if (slack as f64) > cap * 0.45 {
                score += 4.0 * ((slack as f64 / cap) - 0.45);
