}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but nonzero post-residual).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward if the next item can fit into the post-residual,
    // penalize if post-residual is a near-miss for the next item (wasted space).
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 4.0 * (next_item_size as f64 / 100.0);
        } else if next_item_size - post_residual.min(next_item_size) <= 10 {
            score += 6.0; // near-miss dead space for the known next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    if bin_residual < bin_capacity {
        score -= 0.05 * open_pressure;
    }

    // New-bin candidate handling: opening a bin is expensive early and when
    // existing bins fit reasonably well; cheap late in the stream with big items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 60.0
            - 30.0 * item_frac
            + 25.0 * (1.0 - progress)
            + 0.3 * open_bins_count as f64;
        // If alternatives are scarce, allow new bins more readily.
        if fitting_bins_count <= 1 {
            new_bin_score -= 20.0;
        }
        // If mean residual is large, existing bins are roomy: discourage new bin.
        new_bin_score += mean_residual / 10.0;
        score += new_bin_score;
    }

    score
}

