    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - rn) * (1.0 - rn) * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 + 3.0 * progress;
    }

    // New-bin candidate: penalize relative to mean residual so we only open
    // a new bin when existing bins have poor residuals
    if bin_residual == bin_capacity {
        score += 1.0 + mean_residual / c + 2.0 * progress;
        // But if next item is large and this item leaves good residual, soften
