        if next_item_size as f64 <= r {
            score -= 0.3 * (1.0 - progress);
        }
    }

    // Mild penalty for proliferating open bins
    score += 0.01 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into fractional classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1 fraction of bin left after placement

    // Class boundaries at 1/4, 1/2, 3/4 of capacity.
    // Dead-space penalty grows superlinearly for small post residuals,
    // but residuals in the "harmonic sweet spots" (exact divisors of 100)
    // are rewarded.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score -= 25.0; // tiny dead space, nearly perfect
    } else if post_residual % 10 == 0 {
        score -= 12.0; // harmonic class: multiple of 10 pairs well with 10..80 items
    } else if post_residual % 5 == 0 {
        score -= 6.0; // half-harmonic class
    } else {
        // Non-harmonic residual: penalize based on how far from nearest multiple of 10.
        let dist = (post_residual % 10).min(10 - post_residual % 10);
        score += dist as f64 * 1.5;
    }

    // Fractional class coupling: prefer keeping residual in usable bands.
    if frac > 0.5 {
        score -= 5.0; // bin still half full after placement: flexible
    } else if frac < 0.1 && post_residual > 0 {
        score += 8.0; // sliver residual is likely dead space
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.3;
        if post_residual == next_item_size {
            score -= 15.0; // chain of perfect fits
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; slightly penalize leaving awkward gaps.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and we want parallel capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        // Base cost of a fresh bin, discounted early in the stream.
        score = cap as f64 * (1.0 + 0.5 * (1.0 - progress));
        // A new bin is good for very large items that would leave bad slivers.
        if item_frac > 0.5 && post_residual > 0 && post_residual < 20 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (tighter than average bins get priority).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let dr = post_residual as f64;

    // Tightness reward: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (dr / cap);
    score -= 42.0 * tightness * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes.
    if post_residual > 0 && post_residual < 4 {
        score -= 14.0;
    } else if post_residual >= 4 && post_residual < 10 {
        score += 32.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Lookahead coupling: reward when next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 175.0;
            } else if slack < 8 {
                score -= 60.0;
            } else if slack < 20 {
                score -= 32.0;
            } else {
                score -= 15.0;
            }
            // chain: slack can still host the current item size again
            if slack >= item_size as u32 && slack.saturating_sub(item_size) < 6 {
                score -= 12.0;
            }
            // two-step lookahead: after next item, room for another next
            if slack >= next_item_size {
                score -= 11.0;
            }
            // penalize oversized slack (wasted interior space)
            if slack as f64 > cap * 0.45 {
                score += 4.0 * ((slack as f64 / cap) - 0.45);
            }
            // slack matching mean residual predicts future fits
            if slack > 0 && (slack as f64 - mean_residual).abs() < 4.0 {
                score -= 8.0;
            }
        } else {
            if fitting_bins_count == 1 {
                score += 30.0;
            }
            if bin_residual >= next_item_size && post_residual < next_item_size {
                score += 10.0;
            }
            score += 8.0;
        }
        // stranded-space penalty.
        if post_residual > 0 && post_residual < next_item_size {
            let stranded = next_item_size as f64 - dr;
            score += 0.40 * stranded;
            if fitting_bins_count <= 2 {
                score += 6.0;
            }
            // anti-fragmentation: half-unusable residual
            if (post_residual as f64) < (next_item_size as f64) * 0.5 {
                score += 5.0 * (1.0 - dr / next_item_size as f64);
            }
        }
        // two-item exact match.
        if item_size as u64 + next_item_size as u64 == bin_residual as u64 {
            score -= 26.0;
        }
        // waste ratio lookahead.
        if post_residual > 0 {
            let waste = dr / next_item_size as f64;
            if waste >= 2.0 {
                score += 6.0 * (waste - 2.0).min(10.0);
            }
        }
        if post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next >= 1 && after_next <= 5 {
                score -= 15.0;
            }
            if after_next > 0 && (after_next as f64) < mean_residual * 0.35 {
                score += 9.0;
            }
        }
    }

    // Last-chance logic: only fitting bin -> favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        if post_residual == 0 {
            score -= 200.0;
        } else if post_residual >= 12 {
            score -= 48.0;
        } else if post_residual >= 6 {
            score -= 30.0;
        } else {
            score -= 18.0;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 4.0 {
            score -= 45.0;
        } else if mean_gap < 12.0 {
            score += 15.0;
        } else {
            score += 45.0 + mean_gap;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 6.0;
        if open_bins_count > 4 && mean_residual < item_size as f64 {
            score -= 14.0;
        }
        if fitting_bins_count >= 3 {
            score += 12.0;
        }
        if next_item_size > item_size && mean_gap >= 4.0 {
            score += 8.0;
        }
        // block new bin when an open bin would be left nearly perfect
        if next_item_size > 0 && bin_residual.saturating_sub(next_item_size) <= 3 && fitting_bins_count >= 1 {
            score += 20.0;
        }
        // late-stream compaction resistance
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 12.0 * progress;
        }
        // refuse fresh bin when mean residual could host next item
        if next_item_size > 0 && (mean_residual - next_item_size as f64).abs() < 3.0 {
            score += 15.0;
        }
        if progress > 0.35 && fitting_bins_count >= 2 {
            score += 4.0 * progress;
        }
        // allow fresh bin early when existing bins cannot chain next item
        if progress < 0.25 && fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.25 {
            score -= 10.0;
        }
    } else {
        let fill_ratio = 1.0 - (bin_residual as f64 / cap);
        if fill_ratio > 0.75 && post_residual < next_item_size as f64 {
            score -= 5.0 * fill_ratio;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let pair_fit = (post_residual - next_item_size) as f64 / cap;
            score -= 9.0 * (1.0 - pair_fit);
        }
        if post_residual > 0 && post_residual as f64 <= cap * 0.03 {
            score -= 8.0;
        }
        if fill_ratio > 0.9 && post_residual > 0 {
            score -= 5.0;
        }
        // exact match with next item: zero dead space ahead
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 18.0;
        }
        // residual near multiple of mean item size
        if next_item_size > 0 && mean_residual > 1.0 && post_residual > 0 {
            let ratio = post_residual as f64 / mean_residual;
            let frac = (ratio - ratio.round()).abs();
            if frac < 0.08 {
                score -= 6.0 * (1.0 - frac / 0.08);
            }
        }
        // tightest-fit preference scaled by number of alternatives
        if fitting_bins_count > 1 && bin_residual >= item_size {
            let tight = 1.0 - ((bin_residual - item_size) as f64 / cap);
            score -= 4.0 * tight * ((fitting_bins_count as f64).min(6.0) / 6.0);
        }
    }

    // Balance pressure.
    if open_bins_count > 3 {
        let dev = mean_residual - dr;
        if dev > 20.0 {
            score += dev * 0.3;
        }
    }

    // Fill-ratio term.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 13.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Mean-residual alignment.
    score += 0.22 * (mean_residual - dr);

    // Grid alignment bonus.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

