        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Moderate gaps (10..=20) are semi-dead: mild penalty.
    if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Lookahead: if next item fits the post residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).sqrt() * 1.5 * (0.5 + progress);

