        }
        // If no open bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Small time-dependent exploration term: vary preference across stream
    // to hedge against distribution shift.
    let phase = ((step_index as f64) * 0.017).sin();
