}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong reward for tight fits (cubed, like best-known).
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 42.0 * tightness * tightness * tightness;

    // Perfect fill is a hard win.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space shaping: reward near-zero slivers, penalize small-but-wasted gaps.
    if post_residual > 0 && post_residual < 4 {
        score -= 14.0;
    } else if post_residual >= 4 && post_residual < 10 {
        score += 32.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: reward bins whose leftover can serve the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 175.0;
            } else if slack < 8 {
                score -= 60.0;
            } else if slack < 20 {
                score -= 32.0;
            } else {
                score -= 15.0;
            }
            let after_next = post_residual - next_item_size;
            // Two-step lookahead: bin can host next item AND still fit the item after.
            if after_next >= item_size as u32 {
                score -= 22.0;
            }
