            score -= 6.0;
        }
        // Fresh bin leaving a tiny dead gap is worse than using an open bin.
        if fitting_bins_count == 1 {
            let leftover = bin_capacity - item_size;
            if leftover > 0 && leftover < 10 {
                score -= 26.0;
            }
        }
    }

    score
}

