        score -= 15.0 * (1.0 - norm_pr);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Penalize dead space relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual).abs() / cap;

    // Coupling: post_residual vs lookahead item — reward residual that can host next item
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        if nxt <= pr {
            score -= 6.0 * (1.0 - nxt / cap) * (1.0 - progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for opening new bins late in stream (empty-bin candidate)
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress * progress);
    }

    score
}

