    } else if frac < 0.2 {
        score += 15.0;
    } else if frac < 0.5 {
        score += 5.0;
    } else {
        // roomy leftover: reward, since it can host future items
        score -= 10.0;
    }

    // Harmonic compatibility: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
