            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 + gap / cap * 10.0;
        }
        // modulo harmony: next item leaves a clean fraction after this placement
        let class = (next_item_size % 10) as f64;
        let post_class = (post_residual % 10) as f64;
