            score += 12.0 + diff * 0.25;
        }
    }

    // Penalize tiny unusable leftovers (dead space below minimum item size 1..=10)
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Prefer bins whose residual deviates from the mean (best-fit against average slack)
