        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Lookahead: if the next item would NOT fit in the post residual but WOULD fit
    // in the pre residual, this placement blocks a good follow-up; penalize.
