 if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.5 { score += 5.0 * (1.0 - (post_residual as f64) / (next_item_size as f64)) ; } // reward near-perfect two-item packing: item + next leaves almost nothing
 if next_item_size > 0 && post_residual >= next_item_size { let tail = post_residual - next_item_size ; if tail > 0 && tail <= 2 { score -= 10.0 ; } } // NEW: prefer filling bins whose residual is close to the item (tightest fit wins) scaled by how many alternatives exist
 if fitting_bins_count > 1 { let tight = 1.0 - ((bin_residual - item_size) as f64 / cap) ; score -= 4.0 * tight * ((fitting_bins_count as f64).min (6.0) / 6.0) ; } // NEW: residual-entropy reduction — reward bins whose remaining residual is closest to the global mean residual (keeps residuals uniform and packable)
