    if post_residual > 0 && post_residual < 4 {
        score -= 14.0;
    } else if post_residual >= 4 && post_residual < 10 {
        score += 32.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bonus when only one bin fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Dead-space deviation from mean residual
    score += 0.15 * (pr - mean_residual).abs() / cap;

    // Lookahead: reward residuals that can host the next item, with graded chain bonuses
    let nxt = next_item_size as f64;
    if nxt > 0.0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 175.0;
        } else if slack < 8 {
            score -= 60.0;
        } else if slack < 20 {
            score -= 32.0;
        } else {
            score -= 15.0;
        }
        // two-step chain: after next item there is room for the current item again
        let after_next = slack;
        if after_next >= item_size {
            score -= 22.0;
        }
        // dead-space avoidance: slack too small for the mean item
        if slack > 0 && (slack as f64) < mean_residual * 0.3 {
            score += 7.0 - 3.0 * progress;
        }
        // perfect chain: slack fits current item almost exactly
        if slack >= item_size && slack - item_size < 6 {
            score -= 12.0;
        }
        // three-step lookahead: room for next item again after that
        let after_three = after_next as i64 - next_item_size as i64;
        if after_three >= 0 && (after_three as u64) <= (item_size as u64 + next_item_size as u64) {
            score -= 9.0;
        }
        // penalize oversized leftover interior space
        if (slack as f64) > cap * 0.45 {
            score += 4.0 * ((slack as f64 / cap) - 0.45);
        }
        // slack close to mean residual = predictable future fits
        if slack > 0 && (slack as f64 - mean_residual).abs() < 4.0 {
            score -= 8.0;
        }
        // exact two-item fit: item + next == residual
        if item_size as u64 + next_item_size as u64 == bin_residual as u64 {
            score -= 26.0;
        }
    } else if nxt > 0.0 {
        // next item will NOT fit here: strand penalty, worse with fewer alternatives
        let stranded = nxt - pr;
        score += 0.40 * stranded;
        if fitting_bins_count <= 2 {
            score += 6.0;
        }
        if fitting_bins_count == 1 {
            score += 30.0;
        }
        score += 8.0;
    }

    // Waste ratio penalty: post_residual much larger than next item
    if post_residual > 0 && next_item_size > 0 {
        let waste = post_residual as f64 / next_item_size as f64;
        if waste >= 2.0 {
            score += 6.0 * (waste - 2.0).min(10.0);
        }
    }

    // Anti-fragmentation: post_residual too small to be useful for next item
    if post_residual > 0 && next_item_size > 0 && (post_residual as f64) < nxt * 0.5 {
        score += 5.0 * (1.0 - pr / nxt);
    }

    // Near-perfect tail after next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let tail = post_residual - next_item_size;
        if tail > 0 && tail <= 5 {
            score -= 15.0;
        }
        if tail > 0 && (tail as f64) < mean_residual * 0.35 {
            score += 9.0;
        }
    }

    // ===== New-bin candidate gating =====
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 4.0 {
            score -= 45.0;
        } else if mean_gap < 12.0 {
            score += 15.0;
        } else {
            score += 45.0 + mean_gap;
        }
        score += (1.0 - progress) * 6.0;
        if open_bins_count > 4 && mean_residual < item_size as f64 {
            score -= 14.0;
        }
        if fitting_bins_count >= 3 {
            score += 12.0;
        }
        if next_item_size > item_size && mean_gap >= 4.0 {
            score += 8.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && next_item_size as f64 <= mean_residual {
            score += 10.0;
        }
        // block new bin when an open bin would be left nearly perfect
        if next_item_size > 0 && bin_residual.saturating_sub(next_item_size) <= 3 && fitting_bins_count >= 1 {
            score += 20.0;
        }
        // late-stream resistance
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 12.0 * progress;
        }
        // refuse fresh bin when mean residual could host next item
        if next_item_size > 0 && next_item_size as f64 <= mean_residual * 0.9 {
            score += 7.0;
        }
        if next_item_size > 0 && (mean_residual - nxt).abs() < 3.0 {
            score += 15.0;
        }
        if progress > 0.35 && fitting_bins_count >= 2 {
            score += 4.0 * progress;
        }
        // allow fresh bin early when existing bins cannot chain next item
        if progress < 0.25 && fitting_bins_count >= 1 && nxt > mean_residual * 1.25 {
            score -= 10.0;
        }
        if progress < 0.3 && fitting_bins_count >= 1 && (cap - mean_residual) < 0.35 * cap {
            score -= 6.0;
        }
    } else {
        // Existing-bin refinements
        let fill_ratio = 1.0 - (bin_residual as f64 / cap);
        if fill_ratio > 0.75 && post_residual < next_item_size as f64 {
            score -= 5.0 * fill_ratio;
        }
        if fill_ratio > 0.9 && post_residual > 0 {
            score -= 5.0;
        }
        if fill_ratio > 0.95 && post_residual > 0 {
            score -= 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 18.0;
        }
        // residual near a multiple of mean item size
        if next_item_size > 0 && mean_residual > 1.0 && post_residual > 0 {
            let ratio = pr / mean_residual;
            let frac = (ratio - ratio.round()).abs();
            if frac < 0.08 {
                score -= 6.0 * (1.0 - frac / 0.08);
            }
        }
        // prefer bins whose residual is close to the item, scaled by alternatives
        if fitting_bins_count > 1 {
            let tight = 1.0 - ((bin_residual - item_size) as f64 / cap);
            score -= 4.0 * tight * ((fitting_bins_count as f64).min(6.0) / 6.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Primary: strong pull toward tight fits (small post_residual).
    score += 3.0 * (post_residual as f64 / cap);

    // Harmonic class of post_residual: dead space in "awkward" classes is worse.
    // Class 0 (exact fill) is best; classes near half-capacity waste most.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fit reward
    } else {
        // Modulo-10 class penalty: residuals in [1..10] are nearly dead.
        let m = pr % 10;
        score += 2.0 * (10 - m) as f64;
        // Integer-division thresholds: pr in mid band (25..=75) is hard to reuse.
        let band = pr / 25; // 0,1,2,3
        score += [0.0, 6.0, 10.0, 4.0][band.min(3) as usize];
    }

    // Lookahead coupling: reward if next item fits into post_residual exactly or well.
    if next_item_size > 0 && next_item_size <= pr {
        let nxt_post = pr - next_item_size;
        score -= 8.0;
        if nxt_post == 0 {
            score -= 12.0; // chain of perfect fills
        } else if nxt_post < 10 {
            score += 3.0; // leaves near-dead sliver after next
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; residual becomes dead space weighted by size.
        score += 0.05 * (pr as f64) * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current item is large
    // (keeps a big fresh residual for future items) or stream is early.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // Penalize opening new bins for small items / many open bins.
        score += 30.0 - 25.0 * frac;
        score += 0.8 * open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress; // later in stream, prefer filling existing bins
        // If no existing bin can fit, this is forced anyway; soften penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Large item into fresh bin keeps harmonic-friendly residual (100 - size).
        if item_size % 10 == 0 && item_size >= 40 {
            score -= 6.0;
        }
    }

    // Mild preference for bins with residual close to mean (balance open bins).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs() / cap);

    score
}

