            score -= 25.0;
        } else if post_residual >= next_item_size {
            // next item fits, but leaves more fragmentation; mild reward
            // proportional to how well post_residual matches next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
