            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(40.0);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins whose residual is already small (consolidation): placing
    // into a nearly-full bin keeps many open bins usable.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
