        // open bins would leave bad post_residuals.
        score += 12.0;
        // Early in stream, new bins are cheap and preserve flexibility;
        // late in stream, prefer filling existing bins.
        score += 20.0 * (1.0 - t);
        // If many bins are open, discourage one more.
        score += 0.5 * open_bins_count as f64;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

