    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let dr = post_residual as f64;

    // Tightness reward: smaller post_residual (relative to capacity) is better.
    let tightness = 1.0 - (dr / cap);
    score -= 42.0 * tightness * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: tiny residuals are nearly perfect, small ones are wasted.
    if post_residual > 0 && post_residual < 4 {
        score -= 14.0;
    } else if post_residual >= 4 && post_residual < 10 {
        score += 32.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Harmonic classes of capacity: residual near halves/quarters of capacity.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (dr - half).abs() < 3.0 {
        score -= 15.0;
    } else if (dr - quarter).abs() < 3.0 {
        score -= 7.0;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Lookahead coupling: reward when next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 175.0;
            } else if slack < 8 {
                score -= 60.0;
            } else if slack < 20 {
                score -= 32.0;
            } else {
                score -= 15.0;
            }
            let after_next = post_residual - next_item_size;
            if after_next >= item_size as u32 {
                score -= 22.0;
            }
            // dead-space avoidance — penalize slack too small for the mean item, scaled by stream progress
            if slack > 0 && (slack as f64) < mean_residual * 0.3 {
                score += 7.0 - 3.0 * progress;
            }
            // reward slack that still fits the item after next exactly (perfect chain)
            if slack >= item_size as u32 && slack.saturating_sub(item_size) < 6 {
                score -= 12.0;
            }
            // two-step lookahead — bin can host next item AND the one after it
            if after_next >= next_item_size {
                score -= 11.0;
            }
            // penalize slack that is too large relative to bin capacity (wasted interior space)
            if (slack as f64) > cap * 0.45 {
                score += 4.0 * ((slack as f64 / cap) - 0.45);
            }
            // dead-space kill — reward slack that fits a third consecutive item
            let after_three = after_next as i64 - next_item_size as i64;
            if after_three >= 0 && (after_three as u64) <= (item_size as u64 + next_item_size as u64) {
                score -= 9.0;
            }
            // prefer bins whose post-fit slack matches the mean residual (predictable future fits)
            if slack > 0 && (slack as f64 - mean_residual).abs() < 4.0 {
                score -= 8.0;
            }
            // pair-fit shaping: prefer post residual that fits next snugly
            let pair_fit = slack as f64 / cap;
            score -= 9.0 * (1.0 - pair_fit);
        } else {
            // next item won't fit here: penalize if this was the only fitting bin
            if fitting_bins_count == 1 {
                score += 30.0;
            }
            // reward if the current bin_residual would have fit the next item
            if bin_residual >= next_item_size && post_residual < next_item_size {
                score += 10.0;
            }
            score += 8.0;
        }
        // stranded-space penalty: post residual is too small for the next item
        if post_residual > 0 && post_residual < next_item_size {
            let stranded = next_item_size as f64 - dr;
            score += 0.40 * stranded;
            if fitting_bins_count <= 2 {
                score += 6.0;
            }
        }
        // two-item exact match: item + next exactly fills the bin
        if item_size as u64 + next_item_size as u64 == bin_residual as u64 {
            score -= 26.0;
        }
        // waste ratio lookahead: avoid leaving residuals far larger than next item
        if post_residual > 0 {
            let waste = dr / next_item_size as f64;
            if waste >= 2.0 {
                score += 6.0 * (waste - 2.0).min(10.0);
            }
        }
        if post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next >= 1 && after_next <= 5 {
                score -= 15.0;
            }
            if after_next > 0 && (after_next as f64) < mean_residual * 0.35 {
                score += 9.0;
            }
        }
        // exact match of post residual with next item: zero dead space ahead
        if post_residual == next_item_size {
            score -= 18.0;
        }
        // anti-fragmentation — penalize post_residual that strands a sliver the next item cannot use
        if post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.5 {
            score += 5.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
        // near-perfect two-item packing: item + next leaves almost nothing
        if post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > 0 && tail <= 2 {
                score -= 10.0;
            }
        }
    }

    // Last-chance logic: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        if post_residual == 0 {
            score -= 200.0;
        } else if post_residual >= 12 {
            score -= 48.0;
        } else if post_residual >= 6 {
            score -= 30.0;
        } else {
            score -= 18.0;
        }
    }

    // New-bin candidate: attractive only when open bins lack room for the item.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 4.0 {
            score -= 45.0;
        } else if mean_gap < 12.0 {
            score += 15.0;
        } else {
            score += 45.0 + mean_gap;
        }
        score += (1.0 - progress) * 6.0;
        // discourage opening new bins when many bins can still fit the item
        if open_bins_count > 4 && mean_residual < item_size as f64 {
            score -= 14.0;
        }
        if fitting_bins_count >= 3 {
            score += 12.0;
        }
        // next item larger than current: opening a fresh bin may be wiser
        if next_item_size > item_size && mean_gap >= 4.0 {
            score += 8.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && next_item_size as f64 <= mean_residual {
            score += 10.0;
        }
        // block new-bin opening when some open bin would be left nearly perfect
        if next_item_size > 0 && bin_residual.saturating_sub(next_item_size) <= 3 && fitting_bins_count >= 1 {
            score += 20.0;
        }
        // stronger late-stream new-bin resistance — compact into existing bins as the stream ends
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 12.0 * progress;
        }
        // refuse a fresh bin when the next item could still squeeze into mean residual space
        if next_item_size > 0 && next_item_size as f64 <= mean_residual * 0.9 {
            score += 7.0;
        }
        // harder resistance when mean residual alone nearly fits next item exactly
        if next_item_size > 0 && (mean_residual - next_item_size as f64).abs() < 3.0 {
            score += 15.0;
        }
        // mid-stream new-bin resistance scales with how many bins can still take the item
        if progress > 0.35 && fitting_bins_count >= 2 {
            score += 4.0 * progress;
        }
        // allow a fresh bin early when existing bins are too full to chain the next item
        if progress < 0.25 && fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.25 {
            score -= 10.0;
        }
        // open a fresh bin early when the current item barely fits anywhere
        if progress < 0.3 && fitting_bins_count >= 1 && (bin_capacity as f64 - mean_residual) < 0.35 * cap {
            score -= 6.0;
        }
    } else {
        // heavily-filled bins that strand the next item get a small bonus (keep them tight)
        let fill_ratio = 1.0 - (bin_residual as f64 / cap);
        if fill_ratio > 0.75 && post_residual < next_item_size as f64 {
            score -= 5.0 * fill_ratio;
        }
        // pair-fit shaping for bins that can host the next item
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let pair_fit = (post_residual - next_item_size) as f64 / cap;
            score -= 9.0 * (1.0 - pair_fit);
        }
        if post_residual > 0 && post_residual as f64 <= cap * 0.03 {
            score -= 8.0;
        }
        // extra compaction pressure on very full bins
        if fill_ratio > 0.9 && post_residual > 0 {
            score -= 5.0;
        }
        if fill_ratio > 0.95 && post_residual > 0 {
            score -= 4.0;
        }
        // mild preference for bins whose residual is a near-exact multiple of the mean item size
        if next_item_size > 0 && mean_residual > 1.0 && post_residual > 0 {
            let ratio = post_residual as f64 / mean_residual;
            let frac = (ratio - ratio.round()).abs();
            if frac < 0.08 {
                score -= 6.0 * (1.0 - frac / 0.08);
            }
        }
        // prefer filling bins whose residual is close to the item (tightest fit wins)
        if fitting_bins_count > 1 && bin_residual >= item_size {
            let tight = 1.0 - ((bin_residual - item_size) as f64 / cap);
            score -= 4.0 * tight * ((fitting_bins_count as f64).min(6.0) / 6.0);
        }
    }

    // Balance pressure: penalize bins far below mean residual when many bins open.
    if open_bins_count > 3 {
        let dev = mean_residual - dr;
        if dev > 20.0 {
            score += dev * 0.3;
        }
    }

    // Fill-ratio term: prefer bins that are already heavily filled,
    // scaled by log of open bins count.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 13.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Mean-residual alignment: reward bins whose post residual tracks the mean.
    score += 0.22 * (mean_residual - dr);

    // Grid alignment bonus.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let dr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };

    // Strong reward for tight fits (cubic tightness).
    let tightness = 1.0 - (dr / cap);
    score -= 42.0 * tightness * tightness * tightness;

    // Perfect fill is the ideal outcome.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: tiny unusable gaps are waste.
    if post_residual > 0 && post_residual < 4 {
        score -= 14.0;
    } else if post_residual >= 4 && post_residual < 10 {
        score += 32.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

