    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 175.0;
            } else if slack < 8 {
                score -= 60.0;
            } else if slack < 20 {
                score -= 32.0;
            } else {
                score -= 15.0;
            }
            let after_next = post_residual - next_item_size;
            if after_next >= item_size as u32 {
                score -= 22.0;
            }
            // Penalize slack too small for the mean item, scaled by progress.
            if slack > 0 && (slack as f64) < mean_residual * 0.3 {
                score += 7.0 - 3.0 * progress;
            }
            // Reward slack that still fits the item after next nearly exactly.
            if slack >= item_size as u32 && slack.saturating_sub(item_size) < 6 {
                score -= 12.0;
            }
            // Two-step lookahead — bin can host next item AND the one after it.
            if after_next >= next_item_size {
                score -= 11.0;
            }
            // Penalize slack too large relative to capacity (wasted interior space).
            if (slack as f64) > cap * 0.45 {
                score += 4.0 * ((slack as f64 / cap) - 0.45);
            }
            // Prefer slack matching the mean residual (predictable future fits).
            if slack > 0 && (slack as f64 - mean_residual).abs() < 4.0 {
                score -= 8.0;
            }
            // Small tail after next item is near-perfect packing.
            if after_next > 0 && after_next <= 5 {
                score -= 15.0;
            }
        } else {
            if fitting_bins_count == 1 {
                score += 30.0;
            }
            if bin_residual >= next_item_size && post_residual < next_item_size {
