        }
        if item_size as u64 + next_item_size as u64 == bin_residual as u64 {
            score -= 26.0;
        }
        // Penalize post_residual that strands a sliver the next item cannot use.
        if post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.5 {
            score += 5.0 * (1.0 - dr / next_item_size as f64);
        }
        // Waste ratio penalty for oversized leftovers.
        if post_residual > 0 {
            let waste = post_residual as f64 / next_item_size as f64;
            if waste >= 2.0 {
                score += 6.0 * (waste - 2.0).min(10.0);
            }
        }
    }

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && (post_residual == 0 || post_residual >= 10) {
        score -= 40.0;
    }

    // Open-bin pressure: mild, scaled by stream progress.
    score += open_bins_count as f64 * (0.8 + 1.2 * progress);

    // Pull toward mean residual (balanced packing).
    score += 0.15 * (mean_residual - dr).abs();

    // Prefer filling bins whose residual is close to the item (tightest fit).
    if fitting_bins_count > 1 && bin_residual >= item_size {
        let tight = 1.0 - ((bin_residual - item_size) as f64 / cap);
