        if fill_ratio > 0.9 && post_residual > 0 {
            score -= 5.0;
        }
        if fill_ratio > 0.95 && post_residual > 0 {
            score -= 4.0;
        }
        if post_residual > 0 && dr <= cap * 0.03 {
            score -= 8.0;
        }
    }

    // New-bin candidate: baseline cost, modulated by stream state.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 4.0 {
            score -= 45.0;
        } else if mean_gap < 12.0 {
            score += 15.0;
        } else {
            score += 45.0 + mean_gap;
        }
        score += (1.0 - progress) * 6.0;
        if fitting_bins_count >= 3 {
            score += 12.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && next_item_size as f64 <= mean_residual * 0.9 {
            score += 10.0;
        }
        // Block new-bin opening when some open bin would be left nearly perfect.
        if next_item_size > 0 && bin_residual.saturating_sub(next_item_size) <= 3 && fitting_bins_count >= 1 {
            score += 20.0;
        }
        // Late-stream new-bin resistance — compact into existing bins as the stream ends.
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 12.0 * progress;
        }
        // Mid-stream resistance scales with available alternatives.
        if progress > 0.35 && fitting_bins_count >= 2 {
            score += 4.0 * progress;
        }
        // Allow a fresh bin early when existing bins are too full to chain the next item.
        if progress < 0.25 && fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.25 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 && item_size > mean_residual as u32 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps.
    // A residual that cannot fit even the smallest plausible item (<= 12) is pure waste.
    if post_residual < 12 {
        score += (12 - post_residual) as f64 * 6.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 40.0;
    }

    // Reward good tightness: low post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 8.0;

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin candidate and lightly reward consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: penalize proportionally to how many bins are open.
        score += 15.0 + open_bins_count as f64 * 2.5 + progress * 20.0;
    } else {
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) && post_residual >= 12 {
        // Residual becomes dead space for the known next item: mild penalty.
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (concentrate filling in tighter bins).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    score
}

