pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space that no future item (min size 1, typical >=10) can use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a large awkward residual.
            score += 8.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: prefer consolidating into existing bins (penalize new-bin tendency).
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += crowding * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far above mean, it's a wasteful pick.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap;

    // Time horizon: early in the stream, be pickier (penalize loose fits); late, accept anything.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin should only win when current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = bin_capacity as f64 - 10.0;
        // Early stream with few bins: opening is fine.
        score -= 15.0 * (1.0 - progress);
        // If this is the only fitting bin, opening new bin is worse.
        if fitting_bins_count <= 1 {
            score += 60.0;
        }
        // Crowded state: opening a new bin is expensive.
        score += crowding * 8.0;
        // If next item is small, residual space in new bin is valuable.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let dr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tightness reward (cubic, strengthened).
    let tightness = 1.0 - (dr / cap);
    score -= 42.0 * tightness * tightness * tightness;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: tiny residuals are fine (near-closed bins), mid slivers are waste.
    if post_residual > 0 && post_residual < 4 {
        score -= 14.0;
    } else if post_residual >= 4 && post_residual < 10 {
        score += 32.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Harmonic classes of capacity.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (dr - half).abs() < 3.0 {
        score -= 15.0;
    } else if (dr - quarter).abs() < 3.0 {
        score -= 7.0;
    }

    // Bucket preference: mildly prefer larger residuals.
    let bucket = post_residual / 10;
    score -= (bucket as f64) * 2.5;

    // Lookahead coupling with chain anticipation.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 175.0;
            } else if slack < 8 {
                score -= 60.0;
            } else if slack < 20 {
                score -= 32.0;
            } else {
                score -= 15.0;
            }
            // Chain: slack can host the current item again after next.
            let after_next = post_residual - next_item_size;
            if after_next >= item_size {
                score -= 22.0;
            }
            // Two-step lookahead: bin can host next item AND the one after it.
            if after_next >= next_item_size {
                score -= 11.0;
            }
            // Dead-space kill: penalize slack too small for the mean item, scaled by progress.
