                score += 7.0 - 3.0 * progress;
            }
            // Reward slack that fits the item after next almost exactly (perfect chain).
            if slack >= item_size && slack.saturating_sub(item_size) < 6 {
                score -= 12.0;
            }
            // Penalize slack that is too large relative to bin capacity (wasted interior space).
            if (slack as f64) > cap * 0.45 {
                score += 4.0 * ((slack as f64 / cap) - 0.45);
            }
            // Prefer slack that matches the mean residual (predictable future fits).
