            score += 7.0;
        }
        if next_item_size > 0 && (mean_residual - next_item_size as f64).abs() < 3.0 {
            score += 15.0;
        }
        // Mid-stream resistance scales with fitting alternatives.
        if progress > 0.35 && fitting_bins_count >= 2 {
            score += 4.0 * progress;
        }
        // Allow a fresh bin early when existing bins are too full to chain the next item.
        if progress < 0.25 && fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.25 {
            score -= 10.0;
        }
        // Fresh-bin appeal when the item is large relative to mean residual.
        if item_size as f64 > mean_residual * 1.6 && fitting_bins_count >= 1 && progress < 0.5 {
            score -= 8.0;
        }
        // If every fitting bin would strand a large dead zone, a fresh bin is preferable.
        if fitting_bins_count >= 1 && item_size as f64 >= mean_residual {
            let worst_strand = item_size as f64 - mean_residual;
            if worst_strand > cap * 0.25 {
                score -= 5.0;
            }
        }
    } else {
        let fill_ratio = 1.0 - (bin_residual as f64 / cap);
        if fill_ratio > 0.75 && post_residual < next_item_size as f64 {
            score -= 5.0 * fill_ratio;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let pair_fit = (post_residual - next_item_size) as f64 / cap;
