            score -= 5.0;
        }
        if fill_ratio > 0.95 && post_residual > 0 {
            score -= 4.0;
        }
        // Reward bins whose remaining space exactly matches the next item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 18.0;
        }
