pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = r / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = r;

    // Smooth progress-weighted dead-space penalty: later in stream, small residuals are worse
    score += 30.0 * (1.0 - progress) * x * x * cap * 0.05;
    score += 40.0 * progress * x * x * x * cap * 0.05;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 15.0 * progress * (1.0 - x).powi(2);

    // Penalize wasteful near-full residual unless next item fits
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= r {
            score -= 10.0 * (1.0 - x) * (nx / cap);
        } else {
            score += 12.0 * x * x;
        }
    } else {
        score += 8.0 * x;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Mild coupling with open bin count and mean residual
    score += 0.5 * open_bins_count as f64 * x;
    score -= 5.0 * (mean_residual / cap - x).abs();

    // New-bin candidate: make it attractive only for large items / poor fits elsewhere
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + 5.0 * (1.0 - (item_size as f64 / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space penalty: small post_residuals (< 10) are nearly unusable
    // since items are >= 1..100, but tiny slivers waste capacity.
    let pr = post_residual;
    if pr <= 5 {
        score += 60.0;
    } else if pr <= 10 {
        score += 25.0;
    } else if pr <= 20 {
        score += 8.0;
    }

    // Harmonic class of post_residual: residuals in classes matching
    // common item sizes (multiples of 5, 10) stay reusable.
    let class = pr % 10;
    if class == 0 {
        score -= 12.0; // divisible by 10: highly reusable
    } else if class == 5 {
        score -= 6.0;  // divisible by 5: moderately reusable
    } else {
        score += (class as f64) * 1.5; // odd slivers penalized
    }

    // Harmonic pairing: if next_item_size divides evenly into post_residual,
    // this bin is on a perfect harmonic chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0; // next item exactly fills this bin
        } else if post_residual > next_item_size {
            let after2 = post_residual - next_item_size;
            if after2 % 10 == 0 {
                score -= 10.0;
            } else if after2 <= 5 {
                score += 20.0; // would create dead sliver for next item
            }
        } else {
            // next item cannot fit here: mild penalty since bin likely closes
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Progress-based tightening: later in the stream, be greedier about
    // filling bins tightly (weight residual more).
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: only attractive when current bin fit is terrible
    // or mean residual across open bins is very low.
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        if mean_fit_gap > 40.0 || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 20.0 + 0.1 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Prefer bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (i.e., when residual is full capacity, demand a premium unless item is large).
    if bin_residual == bin_capacity {
        score += 80.0 - item_size as f64;
    }

    // Lookahead: if next item would exactly fill the post-residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (fill emptier-of-space bins less,
    // keep large residual bins for big items).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

