pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual near zero is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 55.0 * tightness * tightness;

    // Penalize dead space that cannot serve the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0; // bin remains useful for next item
        } else {
            score += (next_item_size - post_residual) as f64 * 0.9; // wasted gap
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.5 {
            score -= 30.0 * fit_ratio;
        } else {
            score += 12.0 * (1.0 - fit_ratio); // very loose fit in lone bin: risky
        }
    }

    // New-bin candidate handling: empty bins are penalized when a decent
    // open bin exists, but favored when open bins are crowded.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        // If mean residual is low (bins nearly full), opening a new bin is fine.
        score += 25.0 * (1.0 - avg_pressure);
        // More open bins => discourage adding yet another unless necessary.
        score += 3.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, avoid opening new bins for small items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress * (1.0 - item_size as f64 / bin_capacity as f64);
    } else {
        // Reward keeping mean residual balanced (avoid many tiny slivers).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.35 * dev;
    }

    // Time-horizon modulation: early on, be aggressive about tight packing
    // (many items remain); late, prioritize just finishing cleanly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * (1.0 - progress);

    // Mild penalty for very large post_residual that nothing in [1,100]
    // typical range can exploit combined with bin's relative fullness.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // sliver creation penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) + prn * (1.0 - prn) * progress;
    score += 20.0 * poly;

    // Penalize large post-residual more strongly as stream advances (dead space late is costly)
    score += (prn * prn * prn) * 30.0 * (0.3 + 0.7 * progress);

    // Reward tight fits (small post residual) with smooth saturating term
    score -= 15.0 * (1.0 - prn).powi(2) * (prn);

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        score += 0.35 * gap;
        if pr >= ni {
            score -= 6.0 * (1.0 - (pr - ni) / cap);
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening fresh bins unless current residual is unusable
    if bin_residual == bin_capacity {
        let waste = if fitting_bins_count > 0 {
            let min_other = mean_residual;
            (min_other - pr).max(0.0)
        } else { 0.0 };
        score += 40.0 - 15.0 * progress + 0.2 * waste;
    }

    // Mild preference for bins below mean residual (balance load)
    score += 0.1 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 are "clean"
    // because typical item sizes (multiples of 10) can still fill them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Modulo-10 harmonic class: reward residuals in the divisible class.
    let class = post_residual % 10;
    match class {
        0 => score -= 18.0,          // perfectly reusable residual
        5 => score += 4.0,           // half-class: only fits 5s, mildly dead
        c if c <= 4 => score += 6.0 + c as f64,   // small slivers are dead space
        _ => score += 2.0,           // 6..9 class: usable by small items
    }

    // Integer-division thresholds on post_residual: classify by quarter-capacity.
    let quarter = bin_capacity / 4;
    if post_residual >= 3 * quarter {
        score -= 8.0; // bin still very roomy, good to keep filling
    } else if post_residual >= 2 * quarter {
        score -= 3.0; // half-full bin: neutral-good
    } else if post_residual >= quarter {
        score += 5.0; // getting tight
    } else if post_residual > 0 {
        score += 14.0; // near-sealed bin, penalize unless it's a perfect class
    } else {
        score -= 20.0; // exact fit: best possible outcome
    }

    // Exact-fit lookahead: if next item fits the post residual exactly, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportionally tighter lookahead fits.
        let tight = next_item_size as f64 / post as f64;
        score -= 10.0 * tight;
    } else if next_item_size > post_residual {
        // Next item cannot use this residual: penalize proportionally to waste.
        score += 6.0 * (1.0 - post / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the bin whose residual class best matches.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin starts from a high base so it is
    // only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 - 10.0 * progress;
        // If the next item is small enough to eventually pair, slightly cheaper.
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 4.0;
        }
        // Many open bins already: discourage hoarding new bins.
        score += 0.8 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins whose residual deviates from the
    // mean in the "useful" direction (larger residual = more future flexibility).
    score -= 0.15 * (post - mean_residual);

    // Small stream-position modulation: early on, keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.05 * post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below minimum item size
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0; // marginal gap, only fits very small items
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: reward if next item can use the leftover gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // leftover cannot serve next item
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> favor consolidation into existing bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: make opening a new bin costly unless the item
    // is large and would leave a very tight fit elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0; // base cost of opening a new bin
        if item_size >= 70 {
            score -= 35.0; // big items pack cleanly into fresh bins
        }
        score += mean_residual * 0.2; // if open bins are roomy, avoid new bin
    }

    // Mild stream-progress adaptation: early on, be conservative about gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect match with the next item: strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: penalize wasted capacity,
        // scaled by how much of the bin is dead.
        let dead = post_residual as f64;
        score += 0.5 * dead + 10.0;
    } else if post_residual == 0 {
        // Last item and bin closed exactly: excellent.
        score -= 50.0;
    }

    // Penalize unusable dead space (smaller than typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins that are tighter than average (fills fuller bins first,
    // best-fit flavor relative to mean residual).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, encourage consolidation into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 1 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that is hard to reuse later (items >= 10 typically).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here: mildly reward leaving usable space.
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize wasting a big residual.
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: make an empty bin less attractive than a decent fit,
    // but attractive when the item is huge and fits would leave bad dead space.
    if bin_residual == bin_capacity {
        let dead = (bin_capacity - item_size) as f64;
        let bad_fit_penalty = if dead > 0.0 && dead < 10.0 { 30.0 } else { 0.0 };
        score = 20.0 + dead * 0.4 + bad_fit_penalty
            - (fitting_bins_count as f64) * 5.0;
    }

    // Time horizon: early in the stream, be more willing to spread items (open bins),
    // late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> encourage
    // filling existing bins rather than opening new ones.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 6.0;
    }
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * post_residual as f64 / bin_capacity as f64;

    // Mean-residual alignment: prefer bins whose residual is close to the mean
    // (keeps the bin portfolio balanced and reusable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (wasted space)
    let mut score = pr * (1.0 + norm_pr * (1.0 + progress));

    // Smooth polynomial coupling of residual with stream progress
    let t = progress;
    score += pr * (t * t * 0.8 + 2.0 * t * (1.0 - t) * 0.4) * (norm_pr * 3.0).tanh();

    // Reward tight fits: subtract bonus when post residual is small
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item_size as f64 * 0.5;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    }

    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= fit_quality * fit_quality * 10.0;
        } else {
            score += 5.0;
        }
    } else {
        // Last item: prioritize minimizing leftover
        score += pr * 0.3;
    }

    // Mild penalty for scattering across many open bins relative to mean residual
    let mean_norm = mean_residual / cap;
    score += (open_bins_count as f64).ln() * (norm_pr - mean_norm).abs() * 4.0;

    // New-bin candidate handling: penalize opening new bin slightly, more early on
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - t) + 8.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small moduli reveal
    // "good" leftover sizes that many item classes can still reuse.
    let pr = post_residual;
    let r4 = (pr % 4) as f64;
    let r10 = (pr % 10) as f64;
    let r25 = (pr % 25) as f64;

    // Perfect-fit reward (zero dead space is always best).
    if pr == 0 {
        score -= 1000.0;
    }

    // Penalize awkward residues: leftover not divisible by common item
    // granularities (10/20/25 classes typical in packing streams).
    if pr > 0 {
        if pr % 10 == 0 { score -= 30.0; }
        else if pr % 5 == 0 { score -= 15.0; }
        else { score += 10.0 + r10 * 0.5; }
        // 25-class harmony (quarter bins)
        if pr % 25 == 0 { score -= 12.0; }
        score += r4 * 0.75;
        score += r25 * 0.1;
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            // next item fits here exactly -> strong reward
            if pr == n {
                score -= 250.0;
            } else {
                // reward proportional to how well n divides into pr
                let fill = n as f64 / pr as f64;
                score -= 40.0 * fill;
                if pr % n == 0 { score -= 25.0; }
            }
        } else {
            // next item cannot fit -> this leftover is dead-ish space
            score += 20.0 + (n - pr) as f64 * 0.6;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits: score already grows
        // with post_residual, add mild tie-break noise via harmonic class
        score += (bin_residual % 7) as f64 * 0.3;
    }

    // New-bin candidate handling: empty bin has large residual; make it
    // attractive only when current bin fits are poor (high post_residual
    // or none fit well). Base new-bin score anchored near capacity.
    if bin_residual == bin_capacity {
        // neutral anchor: slightly worse than a decent fit, better than
        // a terrible one
        score = bin_capacity as f64 * 0.9 - (item_size as f64) * 0.25;
        if fitting_bins_count == 0 {
            score -= 500.0; // nothing else fits: must open new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin can host the next item too
            score -= 10.0;
        }
    }

    // Phase of stream: early on, prefer consolidating (favor low post_residual
    // harder); late, keep more slack available across bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    // Mild pressure from many open bins: prefer filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean-residual coupling: if this bin is below mean residual (already
    // emptier than average), slight penalty; tighter-than-average bins win.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let dr = post_residual as f64;

    // Tightness reward (cubic, stronger).
    let tightness = 1.0 - (dr / cap);
    score -= 42.0 * tightness * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: small residuals are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Harmonic classes of capacity.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (dr - half).abs() < 3.0 {
        score -= 15.0;
    } else if (dr - quarter).abs() < 3.0 {
        score -= 7.0;
    }

    // Bucket preference: mildly prefer larger residuals.
    let bucket = post_residual / 10;
    score -= (bucket as f64) * 2.5;

    // Lookahead coupling: reward when next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 185.0;
            } else if slack < 8 {
                score -= 60.0;
            } else if slack < 20 {
                score -= 34.0;
            } else {
                score -= 15.0;
            }
            // After-next chain: leftover can still absorb item_size again.
            if slack >= item_size as u32 {
                score -= 22.0;
            }
            // Slack near mean residual band: reusable space.
            if slack > 0 {
                let m = mean_residual.max(1.0);
                if (slack as f64) >= m * 0.85 && (slack as f64) <= m * 1.15 {
                    score -= 6.0;
                }
                // Dead-space: slack below smallest plausible future item.
                let min_future = item_size.min(next_item_size) as f64;
                if (slack as f64) < min_future * 0.9 {
                    let dead_frac = 1.0 - (slack as f64 / min_future);
                    let progress = step_index as f64 / total_items.max(1) as f64;
                    score += (2.0 + 4.0 * progress) * dead_frac * 3.0;
                }
                // Near-dead: slack just below next item.
                if (slack as u32) < next_item_size {
                    let near_dead = 1.0 - (slack as f64 / next_item_size as f64);
                    score += 5.0 * near_dead * near_dead;
                }
                // Large slack waste.
                if (slack as f64) > cap * 0.45 {
                    score += 4.0 * ((slack as f64 / cap) - 0.45);
                }
            }
        } else {
            if fitting_bins_count == 1 {
                score += 30.0;
            }
            if bin_residual >= next_item_size && post_residual < next_item_size {
                score += 10.0;
            }
            score += 8.0;
            let stranded = next_item_size as f64 - dr;
            score += 0.40 * stranded;
            if fitting_bins_count <= 2 {
                score += 6.0;
            }
        }
        // Two-item exact match.
        if item_size as u64 + next_item_size as u64 == bin_residual as u64 {
            score -= 26.0;
        }
        // Waste-vs-next-item coupling.
        if post_residual > 0 {
            let waste = post_residual as f64 / next_item_size as f64;
            if waste >= 2.0 {
                score += 6.0 * (waste - 2.0).min(10.0);
            }
        }
        // Post residual exactly next item: strong pair reward.
        if post_residual == next_item_size {
            score -= 18.0;
        }
        // After-next tight band.
        if post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next >= 1 && after_next <= 5 {
                score -= 15.0;
            }
            if after_next > 0 && (after_next as f64) < mean_residual * 0.35 {
                score += 9.0;
            }
        }
    }

    // Last-chance logic: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        if post_residual == 0 {
            score -= 200.0;
        } else if post_residual >= 12 {
            score -= 48.0;
        } else if post_residual >= 6 {
            score -= 30.0;
        } else {
            score -= 18.0;
        }
    }

    // New-bin candidate: attractive only when open bins lack room for the item.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 4.0 {
            score -= 45.0;
        } else if mean_gap < 12.0 {
            score += 15.0;
        } else {
            score += 45.0 + mean_gap;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 6.0;
        if open_bins_count > 4 && mean_residual < item_size as f64 {
            score -= 14.0;
        }
        if fitting_bins_count >= 3 {
            score += 12.0;
        }
        if next_item_size > item_size && mean_gap >= 4.0 {
            score += 8.0;
        }
        // Fresh bin can absorb next item too: mildly attractive.
        if next_item_size > 0 && fitting_bins_count >= 1 && next_item_size <= mean_residual {
            score += 10.0;
        }
        // Fresh bin nearly matches next item exactly.
        if next_item_size > 0 && bin_residual.saturating_sub(next_item_size) <= 3 && fitting_bins_count >= 1 {
            score += 20.0;
        }
        // Late-stream pressure: prefer reusing open bins.
        if progress > 0.6 && fitting_bins_count >= 1 {
            score += 12.0 * progress;
        }
        // Pair-fit check: item + next fits fresh bin exactly.
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 == bin_capacity as u64 {
            score -= 14.0;
        }
        // Fragmented late stream: opening fresh is cheap.
        if progress > 0.7 && mean_residual < item_size as f64 && fitting_bins_count >= 2 {
            score -= 6.0;
        }
    } else {
        // Existing-bin refinements.
        let fill_ratio = 1.0 - (bin_residual as f64 / cap);
        if fill_ratio > 0.9 && post_residual > 0 {
            score -= 5.0;
        }
        if fill_ratio > 0.95 && post_residual > 0 {
            score -= 4.0;
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.5 {
            score += 5.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let d = post_residual - next_item_size;
            if d <= 4 {
                score -= (6.0 - d as f64) * (1.0 + 3.0 / (fitting_bins_count.max(1) as f64));
            }
        }
        if fitting_bins_count > 1 {
            let tight = 1.0 - ((bin_residual - item_size) as f64 / cap);
            score -= 4.0 * tight * ((fitting_bins_count as f64).min(6.0) / 6.0);
        }
        if bin_residual == item_size {
            score -= 14.0;
        }
        if bin_residual > item_size && bin_residual - item_size <= 2 {
            score -= 7.0;
        }
        if post_residual > 0 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            let dr_ratio = dr / cap;
            if dr > mean_residual {
                score += (dr - mean_residual) * (0.10 + 0.15 * progress);
            }
            if dr_ratio < 0.05 && dr > 0 {
                score -= 4.0 * (1.0 - progress);
            }
            if dr_ratio < 0.02 && progress > 0.7 {
                score -= 3.0;
            }
            // Stranded residual between mean and next item.
            if dr > 0 && dr < mean_residual && dr < next_item_size as f64 {
                score += 2.0 * (1.0 - dr / mean_residual.max(1.0));
            }
            if dr > 0 && dr < next_item_size as f64 && dr >= mean_residual {
                score += 2.5 * progress * (1.0 - dr / next_item_size as f64);
            }
        }
    }

    // Balance pressure: penalize bins far below mean residual when many bins open.
    if open_bins_count > 3 {
        let dev = mean_residual - dr;
        if dev > 20.0 {
            score += dev * 0.3;
        }
    }

    // Fill-ratio term.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 13.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Mean-residual alignment.
    score += 0.22 * (mean_residual - dr);

    // Grid alignment bonus.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

