pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let dr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tightness reward (strengthened, cubic).
    let tightness = 1.0 - (dr / cap);
    score -= 42.0 * tightness * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: small residuals are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Harmonic classes of capacity.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (dr - half).abs() < 3.0 {
        score -= 15.0;
    } else if (dr - quarter).abs() < 3.0 {
        score -= 7.0;
    }

    // Bucket preference: mildly prefer larger residuals.
    let bucket = post_residual / 10;
    score -= (bucket as f64) * 2.5;

    // Lookahead coupling: reward when next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 185.0;
            } else if slack < 8 {
                score -= 60.0;
            } else if slack < 20 {
                score -= 34.0;
            } else {
                score -= 15.0;
            }
            // After-next coupling: residual can absorb item again after next item lands.
            let after_next = post_residual - next_item_size;
            if after_next >= item_size {
                score -= 22.0;
            }
            if next_item_size > 0 && after_next >= next_item_size {
                score -= 11.0;
            }
            // Slack close to mean residual: likely reusable by future items.
            if slack > 0 && ((slack as f64) - mean_residual).abs() < 4.0 {
                score -= 8.0;
            }
            // Dead-space guard: slack too small for the smallest plausible future item.
            if slack > 0 {
                let min_future = item_size.min(next_item_size) as f64;
                if (slack as f64) < min_future * 0.9 {
                    let dead_frac = 1.0 - (slack as f64 / min_future);
                    score += (2.0 + 4.0 * progress) * dead_frac * 3.0;
                }
                if (slack as u32) < next_item_size {
                    let near_dead = 1.0 - (slack as f64 / next_item_size as f64);
                    score += 5.0 * near_dead * near_dead;
                    if fitting_bins_count >= 2 {
                        score += 3.0 * near_dead * (fitting_bins_count.min(5) as f64);
                    }
                }
                // Reward slack matching a plausible future item band around mean residual.
                if (slack as f64) >= mean_residual * 0.85 && (slack as f64) <= mean_residual * 1.15 {
                    score -= 6.0;
                }
                if next_item_size > 1 && slack % next_item_size == 0 {
                    score -= 7.0;
                }
            }
            // Very large slack is waste too.
            if (slack as f64) > cap * 0.45 {
                score += 4.0 * ((slack as f64 / cap) - 0.45);
            }
        } else {
            if fitting_bins_count == 1 {
                score += 30.0;
            }
            if bin_residual >= next_item_size && post_residual < next_item_size {
                score += 10.0;
            }
            score += 8.0;
            let stranded = next_item_size as f64 - dr;
            score += 0.40 * stranded;
            if fitting_bins_count <= 2 {
                score += 6.0;
            }
            if next_item_size as f64 > mean_residual {
                score += 0.25 * (next_item_size as f64 - mean_residual).min(20.0);
            }
        }
        // Two-item exact match.
        if item_size as u64 + next_item_size as u64 == bin_residual as u64 {
            score -= 26.0;
        }
        // Waste-vs-next-item coupling.
        if post_residual > 0 {
            let waste = post_residual as f64 / next_item_size as f64;
