            score -= 200.0;
        } else if post_residual >= 12 {
            score -= 48.0;
        } else if post_residual >= 6 {
            score -= 30.0;
        } else {
            score -= 18.0;
        }
    }

    // New-bin candidate: attractive only when open bins lack room for the item.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 4.0 {
            score -= 45.0;
        } else if mean_gap < 12.0 {
            score += 15.0;
        } else {
            score += 45.0 + mean_gap;
        }
        score += (1.0 - progress) * 6.0;
        if open_bins_count > 4 && mean_residual < item_size as f64 {
            score -= 14.0;
        }
        if fitting_bins_count >= 3 {
            score += 12.0;
        }
        // Fresh-bin lookahead: prefer opening when mean residual cannot absorb next item too.
        if next_item_size > 0 && mean_residual < (item_size + next_item_size) as f64 && progress > 0.5 {
            score -= 4.0;
        }
        if progress > 0.7 && mean_residual < item_size as f64 && fitting_bins_count >= 2 {
            score -= 6.0;
        }
        // Fresh-bin bonus when the best fitting bin would strand much of next_item_size.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let best_strand = (bin_residual as f64 - item_size as f64) - next_item_size as f64;
            if best_strand < 0.0 && (-best_strand) > next_item_size as f64 * 0.5 {
                score -= 10.0;
            }
        }
        if next_item_size > 0 && (mean_residual - next_item_size as f64).abs() < 3.0 {
            score += 15.0;
        }
    }

    // Balance pressure: penalize bins far below mean residual when many bins open.
    if open_bins_count > 3 {
        let dev = mean_residual - dr;
        if dev > 20.0 {
            score += dev * 0.3;
        }
    }

    // Fill-ratio term.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 13.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Mean-residual alignment.
    score += 0.22 * (mean_residual - dr);

    // Grid alignment bonus.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // High fill ratio with unusable post residual: keep filling tight bins.
    if fill_ratio > 0.75 && next_item_size > 0 && post_residual < next_item_size {
        score -= 5.0 * fill_ratio;
    }
    if fill_ratio > 0.9 && post_residual > 0 {
        score -= 5.0;
    }
    if fill_ratio > 0.95 && post_residual > 0 {
        score -= 4.0;
    }

    // Pair fit: post residual can host next item with small tail.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let pair_fit = (post_residual - next_item_size) as f64 / cap;
        score -= 9.0 * (1.0 - pair_fit);
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }
    // Post residual close to a multiple of mean residual: likely reusable.
    if next_item_size > 0 && mean_residual > 1.0 && post_residual > 0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = (ratio - ratio.round()).abs();
        if frac < 0.08 {
            score -= 6.0 * (1.0 - frac / 0.08);
        }
    }

    score
}

